INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Eisen-Katana', 'Iron Katana', 'longsword', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3}', '[]', '[]', 'Robustes Langschwert nach östlichem Brauch. Erfordert aber regelmäßige Pflege.', 'A sword forged with historic Eastern techniques. Durable, but requires regular upkeep.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Käsemesser', 'Cheese Knife', 'longsword', 1, '{"attack":15,"defense":0,"critical":0,"max_level":3,"status":"sleep","status_rate":12}', '[]', '[]', 'Man weiß ja nie. Vielleicht trifft man ja mal auf ein laktoseintolerantes Monster.', 'You never know. Maybe one day, you''ll actually find a lactose intolerant monster!');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Knochen-Katana "Wolf"', 'Bone Katana "Wolf"', 'longsword', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3}', '[]', '[]', 'Verbessertes Langschwert aus Knochen. Sein Rücken ist von Monsterreißzähnen gesäumt.', 'Improved long sword built on a bone base. The top edge is covered in monster fangs.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Blutschrei', 'Blood Cry', 'longsword', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"status":"blast","status_rate":8}', '[]', '[]', 'Scharfes Langschwert, schlank wie Nerscylla-Beine und genauso tödlich. Bringt im Nahkampf den schnellen Tod.', 'A blade as slim as a Nerscylla leg, and just as deadly. Creep in close and kill prey swiftly.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Winddieb-Krummsäbel', 'Wind Thief Scimitar', 'longsword', 1, '{"attack":15,"defense":0,"critical":15,"max_level":3}', '[]', '[]', 'Schwert aus einem Izuchi-Schwanz. Die dünne Klinge ist wendig und leicht zu handhaben.', 'A sword made from an Izuchi tail. Easy to use, its thin blade is very versatile.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Arzuros-Naginata', 'Arzuros Naginata', 'longsword', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3}', '[]', '[]', 'Eine Naginata aus einer Arzuros-Platte und gehärtetem Erz. Für alle, die Kraft suchen.', 'A sword that blends Arzuros plate with ore. Used by strength-focused barbarians.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Kräuselhieb', 'Frilled Slash', 'longsword', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"status":"blast","status_rate":14}', '[]', '[]', 'Schwert aus Somnacanth-Teilen. Die vielen Klingen machen Hackfleisch aus Feinden.', 'A sword made of Somnacanth parts. Its many blades make mincemeat of foes.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Versteckter Säbel', 'Hidden Saber', 'longsword', 1, '{"attack":15,"defense":0,"critical":25,"max_level":3}', '[]', '[]', 'Eine in Dunkelheit getauchte Sense. Wer das von seiner Klinge reflektierende Mondlicht erblickt, weilt nicht mehr lang auf dieser Welt.', 'Long sword drenched in darkness. Those who glimpse the moonlight reflected off its blade are not long for this world.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Khanga-Schneide', 'Khanga Edge', 'longsword', 1, '{"attack":15,"defense":0,"critical":10,"max_level":3}', '[]', '[]', 'Aus Seregios-Klingen. Wie oft man sie auch poliert, der goldene Glanz wird nie verblassen.', 'Made of Seregios blades, its golden sheen will never fade no matter how many times it is polished.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Daito-Krähe', 'Daito Crow', 'longsword', 1, '{"attack":15,"defense":0,"critical":10,"max_level":3,"status":"poison","status_rate":8}', '[]', '[]', 'Wahre Einsamkeit kennt nur die Klinge, die sogar ihren Besitzer verloren hat.', 'True loneliness is known only by the blade that has lost even its owner.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Finsterlangschwert', 'Sinister Long Sword', 'longsword', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"status":"paralysis","status_rate":10}', '[]', '[]', 'Die leibhaftige Wut eines Magnamalo. Dieses Schwert überwältigt seine Beute mit Leichtigkeit.', 'Magnamalo''s fury incarnate. This sword overwhelms its prey with ease.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Wyvern-Klinge "Verde"', 'Wyvern Blade "Verde"', 'longsword', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"fire","status":"poison","status_rate":8}', '[]', '[]', 'Dunkelgrüne Klinge aus Rathian-Material. Ungeheuer scharf und stark.', 'Dark green blade made from Rathian materials. Incredibly sharp and powerful.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Aknosom-Säbel', 'Aknosom Sabre', 'longsword', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"fire"}', '[]', '[]', 'Prächtig verziertes Schwert aus Aknosom-Teilen. Glüht in einem intensiven Rot.', 'A splendidly decorated sword made of Aknosom parts. Emits an intensely hot red glow.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Dios-Katana', 'Dios Katana', 'longsword', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"fire","status":"paralysis","status_rate":8}', '[]', '[]', 'Ein Langschwert mit Brachydios-Kampfgeist. Es spießt seine Beute auf und explodiert dann.', 'A long sword with a Brachydios'' fighting spirit. It can pierce foes and detonate inside them.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Wyvern-Klinge "Ahorn"', 'Wyvern Blade "Maple"', 'longsword', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"fire"}', '[]', '[]', 'Wyvern-Klinge, gefärbt in den Farben der untergehenden Sonne. Ein einzelner Schwung verbrennt das Umfeld zu Asche.', 'Wyvern blade emblazoned with the hues of the setting sun. A single swing will burn the surrounding area to ash.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Flutschaft', 'Drowning Shaft', 'longsword', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"water"}', '[]', '[]', 'Ein Langschwert gefertigt aus den schwammigen Materialien des Königs-Ludroth. Es ertränkt Feinde sogar an Land.', 'A long sword made of the sponge-like materials of Royal Ludroth. Its blows drown even landlocked foes.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Plesioth-Spritzer', 'Plesioth Splasher', 'longsword', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"water"}', '[]', '[]', 'Ein Langschwert, flink wie ein Plesioth, mit eleganten Flossen. Es versprüht Wasser.', 'A blade as deft as a Plesioth. It shoots pressurized water, and the fins keep it classy.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Shogun-Schneider', 'Shogun Cutter', 'longsword', 1, '{"attack":15,"defense":0,"critical":0,"max_level":3,"element":"water"}', '[]', '[]', 'Eine Sense aus Shogun-Ceanataur-Teilen. Immer eine gute Trumpfkarte.', 'A scythe made from Shogun Ceanataur parts that makes for a potent trump card.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Almudron-Klinge', 'Almudron Blade', 'longsword', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"water"}', '[]', '[]', 'Schwert aus den Schuppen des Almudron. Goldener Schlamm verleiht ihm schönen Glanz.', 'A sword made from Almudron scales. Gold mud inside gives the sword a beautiful sheen.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Kakaru Kumo Naki', 'Kakaru Kumo Naki', 'longsword', 1, '{"attack":15,"defense":0,"critical":10,"max_level":3,"element":"water"}', '[]', '[]', 'Das Katana eines Samurai-Kriegshelden, gleichzeitig schön und tödlich.', 'The katana of a samurai war hero. Beautiful and deadly in equal measure.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Hydra-Tornaria', 'Hydra Tornaria', 'longsword', 1, '{"attack":15,"defense":0,"critical":15,"max_level":3,"element":"water"}', '[]', '[]', 'In diesem Namielle-Langschwert existieren sowohl Licht als auch Dunkelheit. Sein Leuchten ist eine Warnung an Feinde.', 'Dark and light coexist within this Namielle long sword, its glow an ill portent for foes.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Heulender Geist', 'Wailing Ghost', 'longsword', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"thunder"}', '[]', '[]', 'Geschaffen von einem großen Schwertmeister, der von seinem Schüler getötet wurde. Reue und Elend schallen von diesem verhexten Schwert.', 'A sword made by a great swordsman who was killed by a disciple. The cursed sword now echoes with his regrets and despair.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Funkenschlitzer', 'Spark Slicer', 'longsword', 1, '{"attack":15,"defense":0,"critical":15,"max_level":3,"element":"thunder"}', '[]', '[]', 'Schwert aus Tobi-Kadachi-Schuppen. Jeder Schlag ist wie ein mächtiger Blitz.', 'A sword made of Tobi-Kadachi scales. Each strike is like a mighty flash of lightning.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Wyvern-Klinge "Beryll"', 'Wyvern Blade "Beryl"', 'longsword', 1, '{"attack":15,"defense":0,"critical":20,"max_level":3,"element":"thunder"}', '[]', '[]', 'Jeder Schwung dieses jaspisfarbenen Flugwyvern-Schwerts taucht Monster in ein Strombad.', 'Each swing of this jasper-colored Flying Wyvern sword bathes monsters in pools of electricity.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Thronräuber-Blitzschlitzer', 'Usurper''s Boltslicer', 'longsword', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"thunder"}', '[]', '[]', 'Ein wilder König als Waffe. Dieses Langschwert wird selbst mit Göttern fertig.', 'A sword for savage kings. If gods truly exist, this sword could cut them down.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Rey-Tonitrus', 'Rey Tonitrus', 'longsword', 1, '{"attack":15,"defense":0,"critical":0,"max_level":3,"element":"thunder"}', '[]', '[]', 'Ein mit Rey Daus Donner durchwirktes Langschwert. Feinde gehen nach einem Kuss seiner leitfähigen Klinge in die Knie.', 'A long sword imbued with Rey Dau''s thunder. Adversaries buckle with one kiss from its conductive edge.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Blango-Dezimator', 'Blango Decimator', 'longsword', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"ice"}', '[]', '[]', 'Langschwert aus Blangonga-Material. Seine kalte Klinge lässt jeden gefrieren.', 'Long sword made from Blangonga materials. Its cold blade freezes all that approach.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Gletscher-Shotel', 'Glacial Shotel', 'longsword', 1, '{"attack":15,"defense":0,"critical":0,"max_level":3,"element":"ice"}', '[]', '[]', 'Dieses eisige, sorgfältig geschliffene Legiana-Langschwert summt, wenn es seine eleganten Schnittmuster vollführt.', 'This icy, keenly honed Legiana long sword hums as it cuts graceful arcs and figures.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Eiskante', 'Icebrink', 'longsword', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"ice"}', '[]', '[]', 'Ein eisiges Langschwert aus Velkhana-Materialien, das die letzten Schreie seiner Beute in deren Hälsen gefrieren lässt.', 'An icy long sword, crafted from Velkhana materials, that freezes the final cries of prey in their throat.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Krächzklinge', 'Cawscythe', 'longsword', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"dragon"}', '[]', '[]', 'Ein beängstigendes Langschwert, das den Tod verkündet.', 'A haunting long sword that delivers a message of death across the land.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Räuberklinge "Grausamkeit"', 'Reaver "Cruelty"', 'longsword', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"dragon"}', '[]', '[]', 'Eine lebende Klinge aus dem Fleisch und den Knochen eines Dämonjho. Sie besitzt einen mitleidlosen Biss.', 'A living blade made from Deviljho meat and bone, possessing a ruthless bite.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Veldian Ensis', 'Veldian Ensis', 'longsword', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"dragon"}', '[]', '[]', 'Ein Langschwert aus Arkveld-Materialien. Es streckte in der Hand seines Ritters Feinde des idealen Königreichs nieder.', 'A long sword made from Arkveld materials. Its knight-wielder felled any who threatened an ideal kingdom.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Sinclair des Herzogs', 'Duke''s Sinclair', 'longsword', 1, '{"attack":15,"defense":0,"critical":0,"max_level":3,"element":"dragon"}', '[]', '[]', 'So ein Blutvergießen in der Vergangenheit der Klinge... So eine enorme Opferzahl!', 'Such bloodshed in this blade''s past. Its victims counted by the legion.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Blauer-Ältester-Langschwert', 'Azure Elder Long Sword', 'longsword', 1, '{"attack":15,"defense":0,"critical":0,"max_level":3,"element":"dragon"}', '[]', '[]', 'Wie die Windschlange Ibushi ruft dieses Schwert die Macht des Windes herbei.', 'Like Wind Serpent Ibushi, this sword can call forth the power of the wind.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Knochenhammer', 'Bone Hammer', 'hammer', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3}', '[]', '[]', 'Ein Hammer aus Knochen. Leichter und einfacher zu benutzen als sein metallisches Gegenstück.', 'A hammer fashioned from bone. Lighter and easier to use than its metallic counterparts.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Giftiges Monster', 'Venom Monster', 'hammer', 1, '{"attack":45,"defense":0,"critical":0,"max_level":3,"status":"poison","status_rate":12}', '[]', '[]', 'Ungewöhnlich aussehender Hammer. Eine grausame Waffe, die ein tödliches Gift beinhaltet.', 'Hammer noted for its unusual appearance. A terrifying weapon containing a deadly poison.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Chata-Klopper', 'Chata Clobberer', 'hammer', 1, '{"attack":45,"defense":0,"critical":0,"max_level":3}', '[]', '[]', 'Ein dem Kopf eines Chatacabra nachempfundener Hammer. Das Gewicht des Kiefers sorgt für ordentlich Karacho!', 'A hammer designed like the head of a Chatacabra. The weight of its jaw ensures that it packs a punch.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Fünfzackiger Hammer', 'Five-Pronged Hammer', 'hammer', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3}', '[]', '[]', 'Hammer aus Bishaten-Teilen. Beschützt angeblich jene, die keine Gier kennen.', 'A hammer made from Bishaten parts. It''s said it protects those who are free of greed.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Kräuselschlag', 'Frilled Blow', 'hammer', 1, '{"attack":45,"defense":0,"critical":0,"max_level":3,"status":"blast","status_rate":14}', '[]', '[]', 'Hammer aus Somnacanth-Teilen. Trifft Feinde mit dem dunklen Eifer einer Meerjungfrau.', 'A hammer made of Somnacanth parts. It strikes its foes with a mermaid''s dark zeal.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Menetekel', 'Calamitous Portent', 'hammer', 1, '{"attack":25,"defense":0,"critical":15,"max_level":3,"status":"poison","status_rate":8}', '[]', '[]', 'Unheimlicher Hammer mit drei ineinander verschlungenen Remobra. Unheil verkündend.', 'An eerie hammer featuring three intertwined Remobra. It feels quite foreboding.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Kulu-Schnabel', 'Kulu Beak', 'hammer', 1, '{"attack":25,"defense":0,"critical":10,"max_level":3}', '[]', '[]', 'Ein Hammer aus dem robusten Schnabel eines Kulu-Ya-Ku. Was auch immer er trifft, wird sich so schnell nicht wieder aufrappeln.', 'Hammer made from the tough beak of a Kulu-Ya-Ku. Anything hit by it won''t be getting up again in a hurry.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Cluster-Hammer', 'Cluster Hammer', 'hammer', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"status":"blast","status_rate":8}', '[]', '[]', 'Ein mit scharfen Spitzen übersäter Nerscylla-Hammer. Die Qualität der Materialien zeigt sich in seiner einzigartigen Schönheit.', 'A Nerscylla hammer covered in sharp barbs. The quality of the materials used is evident in its unparalleled beauty.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Golm-Hammer', 'Golm Gavel', 'hammer', 1, '{"attack":45,"defense":10,"critical":0,"max_level":3}', '[]', '[]', 'Ein Hammer, der schwere Schläge und Schockwellen wie ein Garangolm erzeugt.', 'A hammer capable of dealing heavy blows and creating mighty shockwaves, as if struck by a Garangolm.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Matraca-Hammer', 'Matraca Hammer', 'hammer', 1, '{"attack":25,"defense":0,"critical":10,"max_level":3}', '[]', '[]', 'Ein Hammer aus Seregios-Schuppen, der Gegner zu Staub zermahlen kann.', 'A hammer forged from the scales of a Seregios. Capable of reducing foes to dust.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Diablos-Hammer', 'Diablos Hammer', 'hammer', 1, '{"attack":45,"defense":15,"critical":0,"max_level":3}', '[]', '[]', 'Hammer, der aus einem vollständigen Diablos-Schwanz hergestellt wurde. Dieses Meisterwerk verfügt über eine verheerende Zerstörungskraft.', 'Hammer made using a Diablos tail in its entirety. This masterwork boasts devastating destructive power.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Finsterhammer', 'Sinister Hammer', 'hammer', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"status":"paralysis","status_rate":10}', '[]', '[]', 'Ein Hammer aus Magnamalo-Teilen. Diese dämonische Waffe sieht aus wie eine alte Rüstung, die einen Pfad der Zerstörung hinterlässt.', 'A hammer made from Magnamalo parts. This demonic weapon is shaped like ancient armor, forging a path of destruction.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Gewehrhammer-Prototyp', 'Gunhammer Prototype', 'hammer', 1, '{"attack":35,"defense":20,"critical":0,"max_level":3,"element":"fire"}', '[]', '[]', 'Hammer aus einer fernen Stadt, der vielerorts Neid aufkommen lässt.', 'Made in a distant town, this hammer is the subject of envy in many workshops.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Kut-Ku-Hacke', 'Kut-Ku Pick', 'hammer', 1, '{"attack":25,"defense":0,"critical":10,"max_level":3,"element":"fire"}', '[]', '[]', 'Der unverzichtbare Yian-Kut-Ku-Hammer dieser Saison. Führe ihn mit Stolz und zeige jedem, dass du verrückt nach Kut-Ku bist!', 'This season''s must-have Yian Kut-Ku hammer. Wield it with pride and show everyone you''re crazy for Kut-Ku!');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Dios-Schwanzhammer', 'Dios Tailhammer', 'hammer', 1, '{"attack":45,"defense":0,"critical":0,"max_level":3,"element":"fire","status":"paralysis","status_rate":8}', '[]', '[]', 'Hammer aus einem Brachydios-Schwanz. Bei jedem Aufprall wird explosiver Schleim in die Luft gesprüht.', 'Hammer made using the tail of a Brachydios. Each impact causes explosive slime to spray through the air.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Rosenhammer', 'Rosenhammer', 'hammer', 1, '{"attack":25,"defense":0,"critical":10,"max_level":3,"element":"fire","status":"poison","status_rate":8}', '[]', '[]', 'Bemerkenswerte Verwendung eines Espinas-Kopfs. Dornige Wut zerschmettert alles.', 'A hammer making striking use of an Espinas head. Thorny rage smashes everything.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Schalenhammer', 'Shell Hammer', 'hammer', 1, '{"attack":45,"defense":20,"critical":0,"max_level":3,"element":"fire","status":"poison","status_rate":8}', '[]', '[]', 'Hammer aus einem Gravios-Panzer. Allein der Anblick der zahlreichen Dornen auf seinem Kopf versetzt Beute in Panik.', 'Hammer fashioned from a Gravios carapace. Just the sight of the numerous spikes on its head send prey into a panic.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Sengende Isshata', 'Scorching Isshata', 'hammer', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"fire"}', '[]', '[]', 'Ein Hammer, dessen Kopf von einer Hitze erfüllt ist, die keine Grenzen kennt.', 'A hammer featuring a head of extreme heat that knows no bounds.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Ludroth-Spritzhammer', 'Ludroth Splashhammer', 'hammer', 1, '{"attack":45,"defense":0,"critical":0,"max_level":3,"element":"water"}', '[]', '[]', 'Ein Hammer gefertigt aus den schwammigen Materialien des Ludroth. Das Wasser darin explodiert auf dem Ziel.', 'A hammer made of the sponge-like materials of Ludroth. The water inside explodes onto the target on impact.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Typ-42-Panzerbrecher', 'Type 42 Shellbuster', 'hammer', 1, '{"attack":45,"defense":20,"critical":0,"max_level":3,"element":"water"}', '[]', '[]', 'Ein Nibelsnarf-Hammer, der durch Panzerungen schlagen kann. Selbst der Panzer eines Drachen ist seiner Kraft nicht gewachsen.', 'A Nibelsnarf hammer capable of smashing through the strongest of shells. Even dragon carapace is no match for its might.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Ceanataurenkopf-Axt', 'Ceanataur Head Axe', 'hammer', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"water"}', '[]', '[]', 'Aus schwer zu verarbeitenden Shogun-Schädelteilen hergestellt, jedoch einfach zu verwenden.', 'Made from tough-to-work-with Shogun head pieces. It''s designed for ease of use.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Almudron-Hammer', 'Almudron Hammer', 'hammer', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"water"}', '[]', '[]', 'Hammer aus Almudron-Teilen. Kräftig genug, um Feinde von den Füßen zu reißen.', 'A hammer crafted from Almudron parts. Its ferocity sweeps foes off their feet.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Plesioth-Kopf', 'Plesioth Head', 'hammer', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"water"}', '[]', '[]', 'Wie ein Plesioth-Kopf geformter Hammer. Greift mit der Kraft eines tobenden Flusses an.', 'Hammer fashioned after the head of a Plesioth. Attacks with the force of a raging river.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Schreckensbeutel', 'Bag o'' Horrors', 'hammer', 1, '{"attack":45,"defense":0,"critical":0,"max_level":3,"element":"thunder"}', '[]', '[]', 'Ein verdächtig aussehender Hammer, geschmückt mit Khezu-Haut. Wenn du deinen Kopf behalten willst, schaue nicht in den Beutel.', 'A suspicious-looking hammer adorned with Khezu hide. Don''t look inside the pouch part if you know what''s good for you.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Blutender Schwinger', 'Bleeding Bopper', 'hammer', 1, '{"attack":45,"defense":0,"critical":0,"max_level":3,"element":"thunder"}', '[]', '[]', 'Ein mörderischer Hammer, von Khezu-Haut umhüllt. Was auch immer in der Tasche ist, wurde "aufgewertet".', 'An ogreish hammer wrapped in Khezu hide. Whatever''s in the bag has been "upgraded."');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Smaragdschläger', 'Emerald Beater', 'hammer', 1, '{"attack":25,"defense":0,"critical":20,"max_level":3,"element":"thunder"}', '[]', '[]', 'Hammer, der dem Kamm von Astalos nachempfunden wurde. Nur die, die den Donnerwyvern nicht fürchten, eignen sich als Träger.', 'Hammer modeled on the crest of the Astalos. Only those who do not fear the Thunder Wyvern are fit to wield it.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Thronräuber-Donner', 'Usurper''s Thunder', 'hammer', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"thunder"}', '[]', '[]', 'Einem dämonischen Donnergott nachempfunden. Kann mit einem Schlag Leben zu Staub reduzieren.', 'A hammer modeled after an evil thunder god. One swing can reduce lives to dust.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Vortex-Hammer', 'Vortex Hammer', 'hammer', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"thunder"}', '[]', '[]', 'Ein Hammer aus Lagiacrus-Hörnern. Wer in seinen Stromfluss hineingerät, wird extremen Blitzattacken ausgesetzt.', 'Hammer made using the horns of the Lagiacrus. Those engulfed by its currents are subjected to extreme lightning attacks.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Eiskern', 'Frozen Core', 'hammer', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"ice"}', '[]', '[]', 'Hammer mit gefrorenem Kern. So kalt, dass ungeschützte Hände sofort einfrieren.', 'A hammer with a frozen core. So cold, touching it will freeze unprotected hands.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Spitzkopf-Hammer', 'Conehead Hammer', 'hammer', 1, '{"attack":45,"defense":0,"critical":0,"max_level":3,"element":"ice"}', '[]', '[]', 'Ein Hammer aus Blango-Teilen. Seine Hiebe sind kalt und lassen die Seele gefrieren.', 'A Hammer made of Blango parts. The cold it gives off with every swing can freeze the soul.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Yeti-Hammer', 'Yeti Hammer', 'hammer', 1, '{"attack":45,"defense":0,"critical":0,"max_level":3,"element":"ice"}', '[]', '[]', 'Eisiger Goss-Harag-Hammer. Folge deinem Instinkt und zerschmettere deine Feinde!', 'An icy Goss Harag hammer. Let your instincts loose and crush your foes!');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Hammer des Wintermonds', 'Hammer of Winter Moon', 'hammer', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"ice"}', '[]', '[]', 'Verkörpert Lunagarons Wildheit. Er verströmt vor dem Gemetzel kalte Luft.', 'Embodying Lunagaron''s ferocity, it releases cold air in preparation for slaughter.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Anmutiger Tod', 'Graceful Death', 'hammer', 1, '{"attack":25,"defense":10,"critical":0,"max_level":3,"element":"dragon"}', '[]', '[]', 'Waffe in der Form eines Rachegeists. Greift nach der Seele jener, die er berührt.', 'A weapon resembling the hand of an evil spirit. Grips the souls of those it has reaped.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Teufelsschuld', 'Devil''s Due', 'hammer', 1, '{"attack":45,"defense":0,"critical":0,"max_level":3,"element":"dragon"}', '[]', '[]', 'Hammer, der die Macht des Dämonjho ausströmt. Der in ihm lebende Zorn lässt die Waffe beim Anblick von Beute anschwellen.', 'Hammer exuding the power of the Deviljho. The rage sealed within causes the weapon to swell upon sighting prey.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Veldian Malleus', 'Veldian Malleus', 'hammer', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"dragon"}', '[]', '[]', 'Ein Hammer aus Arkveld-Materialien. Der unfassbar starke Ritter, der ihn führte, konnte ihn mit einer Hand schwingen.', 'A hammer made from Arkveld materials. The impossibly strong knight who bore this could swing it with one hand.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Herzog-Schmetterer', 'Duke Smiter', 'hammer', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"dragon"}', '[]', '[]', 'Ein Malzeno-Hammer mit einer tödlichen Spitze, die bis ins Mark dringt.', 'A Malzeno hammer, made more lethal through a tapered tip that crushes to the marrow.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Blauer-Ältester-Hammer', 'Azure Elder Hammer', 'hammer', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"dragon"}', '[]', '[]', 'Verkörpert Ibushis Zorn. Bereits ein Schlag des Hammers bringt die Erde zum Beben.', 'A hammer embodying the anger of Ibushi. Even one blow can shake the earth beneath it.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Knochenhorn', 'Bone Horn', 'horn', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"melody":[-1506610944,13552],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Ein einfaches Jagdhorn aus einem hohlen Knochen, dessen Melodie durch den Körper des Zuhörers fährt und verborgene Kräfte weckt.', 'Simple hunting horn made from hollowed bone. Its melody thrums through the listener''s body, awakening hidden powers.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Gift-Capri', 'Poisoned Capri', 'horn', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"status":"poison","status_rate":12,"melody":[14471,11744],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Ein Jagdhorn, gefertigt aus Gypceros-Teilen. Dem Schnabel und Kamm nachempfunden.', 'A hunting horn made from Gypceros parts, modeled after its unique beak and crest.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Paolumu-Horn', 'Lumu Horn', 'horn', 1, '{"attack":15,"defense":0,"critical":10,"max_level":3,"melody":[-349999872,13552],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Ein elegantes Jagdhorn, reich verziert mit dem prächtigen, glänzenden Fell eines lieblichen doch furchterregenden Paolumu.', 'An elegant hunting horn richly decorated with the luxuriant, glossy fur of an adorable yet terrifying Paolumu.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Zurogong I', 'Zurogong Primo', 'horn', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"melody":[-349999872,13552],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Ein Jagdhorn, hergestellt aus Arzuros-Materialien. Sein lieblicher Klang hallt über Berge und Täler.', 'Hunting horn made using materials from the Arzuros. Its dulcet tones echo across mountains.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Kulu-Duda', 'Kulu Duda', 'horn', 1, '{"attack":15,"defense":0,"critical":10,"max_level":3,"melody":[-1506610944,13552],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Verwendet Kulu-Ya-Ku-Leder für einen Klang so schwungvoll wie das rhythmische Schlagen einer Trommel.', 'Uses Kulu-Ya-Ku leather for a jaunty sound like the rhythmical beating of a drum.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Sandflöte', 'Sandpipe', 'horn', 1, '{"attack":35,"defense":15,"critical":0,"max_level":3,"melody":[-349999872,23637],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Wuchtige östliche Waffe, die einer Barroth-Krone ähnelt. Erzeugt liebliche Töne.', 'A horn that resembles a Barroth''s crown. Despite its appearance, it sounds sweet.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Vicello Nulo Vert', 'Vicello Nulo Green', 'horn', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"status":"sleep","status_rate":12,"melody":[25753,12978],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Eine celloähnliche Waffe aus Bnahabra-Teilen. Ein Lähmgift macht Feinde unbeweglich.', 'A cello-like weapon made of a Bnahabra. Uses a paralytic agent that immobilizes foes.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Golm-Trommel', 'Golm Drum', 'horn', 1, '{"attack":35,"defense":10,"critical":0,"max_level":3,"melody":[-1506610944,23637],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Der explosive Schlag dieser Garangolm-Trommel dröhnt in den Herzen der Zuhörer.', 'The explosive sound of this Garangolm drum echoes to the heart of the listener.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Raben-Shamisen', 'Raven Shamisen', 'horn', 1, '{"attack":15,"defense":0,"critical":10,"max_level":3,"status":"poison","status_rate":8,"melody":[3601,28261],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Hergestellt aus dem ganzen Schwanz eines Yian Garuga. Ein melancholisches Klagelied ertönt von seinen drei Saiten.', 'Made using the whole tail of a Yian Garuga. A melancholy melody flows from its three strings.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Streifen-Dragonga', 'Striped Dragonga', 'horn', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"melody":[-349999872,28261],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Ein Jagdhorn aus Tigrex-Material, dessen Wyverngebrüll die Seele erschüttert.', 'A hunting horn made from Tigrex materials. The fierce wyvern roar shakes the soul.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Finsterklang', 'Sinister Strum', 'horn', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"status":"paralysis","status_rate":10,"melody":[-349999872,8255],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Mach dich bereit für deinen großen Auftritt mit dieser dämonischen Laute.', 'Come now, and set the stage for a grand performance with this demonic lute.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Geister-Drachenholz-Horn', 'Spirit Dragonwood Horn', 'horn', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"status":"sleep","status_rate":8,"melody":[-1506610944,15538],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Seltsames Horn östlicher Herkunft. Soll Drachen herbeirufen können.', 'A strange horn made via Eastern techniques. Said to be able to call a dragon.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Kut-Kus Lied', 'Kut-Ku''s Song', 'horn', 1, '{"attack":15,"defense":0,"critical":10,"max_level":3,"element":"fire","melody":[-488356384,11744],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Ein Jagdhorn, das seine besondere Kraft einsetzt, um die Herzen all jener zu berühren, die seinen Klängen lauschen.', 'A hunting horn that uses its special power to stir the hearts of those that hear its song.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Vicello Nulo Rouge', 'Vicello Nulo Red', 'horn', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"fire","melody":[-488356384,12978],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Eine celloähnliche Waffe aus Bnahabra-Teilen. Der heiße Rhythmus macht den Monstern Feuer unterm Hintern.', 'A cello-like weapon made from Bnahabra. Pluck the strings in pizzicato for a melodious flair of sparks and pizzazz.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Anjanath-Summen', 'Anjanath Hum', 'horn', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"fire","melody":[-488356384,23079],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Die ewige Flamme dieses Anjanath-Jagdhorns lässt alles in Reichweite zu Asche werden.', 'The undying flame within this Anjanath hunting horn will see all in its reach burned to ash.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Erhabene Glocke', 'Sublime Bell', 'horn', 1, '{"attack":15,"defense":0,"critical":15,"max_level":3,"element":"fire","melody":[-488356384,23637],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Ein Jagdhorn, das den Klang von Hochzeitsglocken erklingen lässt – fast, als würde es etwas Festliches einleiten...', 'A hunting horn that emits the sound of wedding bells. The sublime chimes almost seem to be summoning something solemn...');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Ajara-Widerhall', 'Ajara Reverberator', 'horn', 1, '{"attack":15,"defense":0,"critical":10,"max_level":3,"element":"fire","status":"paralysis","status_rate":8,"melody":[-1506610944,23079],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Ein Ajarakan-Jagdhorn, das mit seinen sengenden Vibrationen den Himmel erschüttert und all seine Zuhörer zu Großem anspornt.', 'An Ajarakan hunting horn that shakes the skies with searing vibrations, kindling the spirits of listeners.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Rathalos-Feroce', 'Rathalos Feroce', 'horn', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"fire","melody":[-488356384,5157],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Ein wahrer König kennt keine Niederlage. Dieses polierte Stück verkündet den Sieg und ebnet mit seinen kühnen Melodien den Weg zur Herrschaft.', 'A true king knows not defeat. This polished instrument heralds victory and paves the way to dominion with its bold melodies.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Magia-Zauber', 'Magia Charm', 'horn', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"ice","melody":[31011,12562],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Äußerst beliebt ist es bei den Mädels. Seine Melodie hallt sogar im Himmel wider.', 'Popular with girls, this horn produces a light melody that echoes high into the sky.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Froschflöte', 'Frog Flute', 'horn', 1, '{"attack":35,"defense":10,"critical":0,"max_level":3,"element":"water","melody":[434881472,11744],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Horn aus Tetranadon-Teilen. Erzeugt mit dem Wasser im Inneren quakende Töne.', 'A horn made from Tetranadon parts. Makes croaking sounds using the water inside it.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Typ-63-Kriegsorgel', 'Type 63 Warmonica', 'horn', 1, '{"attack":35,"defense":0,"critical":20,"max_level":3,"element":"water","melody":[14471,19299],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Musikalische Waffe in künstlerischem Design. Kann Bewegungen während der Jagd lenken.', 'A musical weapon of artisinal design. Its tones can direct movements while in the midst of the hunt.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Dichterglocke', 'Poetic Bell', 'horn', 1, '{"attack":15,"defense":0,"critical":10,"max_level":3,"element":"water","melody":[434881472,5157],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Elegante Glocke aus dem Nachlass eines berühmten Strategen. Ruft den Tod herbei.', 'An elegant bell left by a famous military strategist. Its clear tone brings death.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Hydros-Horn', 'Hydros Horn', 'horn', 1, '{"attack":15,"defense":0,"critical":15,"max_level":3,"element":"water","melody":[434881472,9408],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Dieses Namielle-Jagdhorn lockt Gegner mit seinem süßen Klang in ihr Verderben.', 'Beckon prey into the darkness through the bewitching song of this Namielle hunting horn.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Vicello Nulo Jaune', 'Vicello Nulo Yellow', 'horn', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"thunder","melody":[25753,12978],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Eine celloähnliche Waffe aus Bnahabra-Teilen. Beim Saitenanschlag wird Elektrizität freigesetzt.', 'A cello-like weapon woven from Bnahabra parts. When its strings are plucked, electricity is released.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Khezu-Horn', 'Khezu Horn', 'horn', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"thunder","melody":[944587776,19299],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Ein gruseliges Jagdhorn, das den abscheulichen Schlund eines Khezu repliziert. Geisterhaft in Form und Klang.', 'Ghastly hunting horn replicating the mouth of a Khezu. Phantasmal shape and melody.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Bluthorn', 'Blood Horn', 'horn', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"thunder","melody":[944587776,19299],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Ein rotes Jagdhorn, das aus der gewickelten Haut eines Roten Khezus gefertigt wurde. Seine Farbe ist äußerst beunruhigend.', 'Red hunting horn made from wrapped Red Khezu hide. Its color is very unsettling.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Smaragdflattern', 'Emerald Flap', 'horn', 1, '{"attack":15,"defense":0,"critical":20,"max_level":3,"element":"thunder","melody":[944587776,8255],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Ein Jagdhorn, gefertigt aus Astalos-Flügeln. Mächtiger Donner hallt in ihm wider.', 'A hunting horn made from the wing membrane of an Astalos. It echoes with mighty thunder.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Fulgur-Horn', 'Fulguring Horn', 'horn', 1, '{"attack":15,"defense":0,"critical":15,"max_level":3,"element":"thunder","melody":[944587776,23079],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Ein Jagdhorn aus Fulgur-Anjanath-Teilen, das die rasenden Blitze im Inneren gerade noch beherrschen kann.', 'A hunting horn, crafted from Fulgur Anjanath parts, that barely contains the furious lightning within it.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Rey-Perun', 'Rey Perun', 'horn', 1, '{"attack":15,"defense":0,"critical":0,"max_level":3,"element":"thunder","melody":[944587776,5157],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Ein mit Rey Daus Donner durchwirktes Jagdhorn. Seine Hymnen kündigen einen Fürsten an und flößen Angst ein.', 'A hunting horn imbued with Rey Dau''s thunder. Its anthems announce the coming of a lord, and invoke fear.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Dodotto-Horn', 'Dodotto Horn', 'horn', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"ice","melody":[1782898432,23079],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Traditionelles Instrument eines Stammes aus dem Land der schneebedeckten Berge.', 'A traditional instrument that is used by tribes that live in the snowy mountain lands.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Bari-Guiro', 'Bariguiro', 'horn', 1, '{"attack":15,"defense":0,"critical":15,"max_level":3,"element":"ice","melody":[1782898432,5157],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Mit den Barioth-Reißzähnen und dem Panzer produziert es einen träumerischen Ton, der seine Opfer bannt.', 'Uses the fangs and carapace of a Barioth to produce a fantastical melody that entrances its prey.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Gletscher-Dudelsack', 'Glacial Bagpipe', 'horn', 1, '{"attack":15,"defense":0,"critical":0,"max_level":3,"element":"ice","melody":[1782898432,8255],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Ein Jagdhorn des anmutig schwebenden Legiana. Es erzeugt eine eisige Melodie von großer Schönheit.', 'A hunting horn of the gracefully soaring Legiana. Produces an icy tune of great beauty.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Eisspiel', 'Icespiel', 'horn', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"ice","melody":[1782898432,17246],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Ein eisiges Jagdhorn aus Velkhana-Teilen, das die letzten Schreie seiner Beute in deren Hälsen gefrieren lässt.', 'An icy hunting horn, crafted from Velkhana parts, that freezes the final cries of prey in their throat.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Vicello Nulo Noir', 'Vicello Nulo Black', 'horn', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"dragon","melody":[3601,12978],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Eine celloähnliche Waffe aus Bnahabra-Teilen. Kann selbst Monster verstummen lassen.', 'A cello-like weapon made of Bnahabra parts. Its melodies are said to silence even dragons.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Veldian Sibilus', 'Veldian Sibilus', 'horn', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"dragon","melody":[-1506610944,32671],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Ein Jagdhorn aus Arkveld-Materialien. Der Ritter, der seinem Volk stets treu diente, wurde heiliggesprochen und zu einer Legende.', 'A hunting horn made from Arkveld materials. Ever a servant of the people, its knight was sainted and became legend.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Herzogsgral', 'Duke''s Grail', 'horn', 1, '{"attack":15,"defense":0,"critical":0,"max_level":3,"element":"dragon","melody":[28629,7225],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Ein Jagdhorn aus Malzeno-Material. Klingt unschuldig und geheimnisvoll zugleich.', 'A hunting horn forged from Malzeno materials. Its melodies are both innocent and mysterious.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Blauer-Ältester-Horn', 'Azure Elder Horn', 'horn', 1, '{"attack":15,"defense":0,"critical":0,"max_level":3,"element":"dragon","melody":[28629,20606],"partner_melody":[-1506610944,13552]}', '[]', '[]', 'Lass Ibushis Einsamkeit über die Lande strömen und die Sterne zum Zittern bringen.', 'Let Ibushi''s solitude swell unyielding over the land, and shake the stars above.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Eisenbogen', 'Iron Bow', 'bow', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3}', '[]', '[]', 'Ein grober Bogen aus Eisen. Trotz der Herstellung in Massenproduktion eine gute Waffe!', 'A crude iron bow that, despite its mass-produced quality, packs quite a punch.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Felynen-Bogen', 'Felyne Bow', 'bow', 1, '{"attack":35,"defense":5,"critical":0,"max_level":3}', '[]', '[]', 'Reizender Bogen, geformt wie ein Felynen-Kopf, aus dessen Maul Pfeile fliegen.', 'A very cute bow, crafted in the shape of a Felyne head whose mouth looses arrows.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Arzuros-Bogen', 'Arzuros Bow', 'bow', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3}', '[]', '[]', 'Großbogen mit typischen Arzuros-Flecken und Fell. Riecht leicht nach Honig.', 'Greatbow with signature Arzuros spotting and fur. Smells faintly of honey.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Dämmerlicht-Bogen', 'Dawn Ray Bow', 'bow', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3}', '[]', '[]', 'Bogen aus blauen Bishaten-Federn. Wie ein Heiligenschein, leuchtet er erhaben auf dem Rücken des Jägers.', 'Made from blue Bishaten feathers. It resembles a halo on your back, glowing with nobility.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Golm-Knochenbogen', 'Golm Bone Bow', 'bow', 1, '{"attack":35,"defense":10,"critical":0,"max_level":3}', '[]', '[]', 'Ein dicker, schildartiger Bogen aus robustem Garangolm-Material. Schießt Pfeile wie Speere.', 'A thick, shield-like bow of sturdy Garangolm material, launching arrows like javelins.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Krähenbogen', 'Crow Bow', 'bow', 1, '{"attack":15,"defense":10,"critical":10,"max_level":3}', '[]', '[]', 'Aus Yian-Garuga-Teilen gefertigt. Das Gift des Monsters verweilt in den Pfeilen, bereit, Beute zu verschlingen.', 'Made from Yian Garuga parts. The monster''s venom covers the arrowheads, ready to poison any prey.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Versteckter Bogen', 'Hidden Bow', 'bow', 1, '{"attack":15,"defense":0,"critical":25,"max_level":3}', '[]', '[]', 'Nachtschwarzer Bogen, dessen Nargacuga-Fell Licht absorbiert. Er ist perfekt für Scharfschützen.', 'An ebon bow, dark as night. Nargacuga fur absorbs light, so it''s perfect for snipers.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Diablos-Hornbeuger', 'Diablos Coilbender', 'bow', 1, '{"attack":35,"defense":15,"critical":0,"max_level":3}', '[]', '[]', 'Starker Jagdbogen aus Diablos-Hörnern. Ihn zu spannen, erfordert große Stärke.', 'A bow made from the resilient twin horns of Diablos. Takes titanic strength to pull back its string.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Tigrex-Bogen', 'Tigrex Archer', 'bow', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3}', '[]', '[]', 'Aus Tigrex-Teilen hergestellt und mit genug Zorn durchtränkt, um Felsen zu zerschlagen.', 'Made from Tigrex parts and infused with enough rage to smash through rock.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Finsterbogen', 'Sinister Bow', 'bow', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3}', '[]', '[]', 'In diesem Bogen steckt die Leidenschaft eines Magnamalo. Gemetzel schürt Groll...', 'The passions of Magnamalo are entombed within. Slaughter fuels rancor...');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Drachenbogen Solar', 'Dragon Bow Solar', 'bow', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3}', '[]', '[]', 'Mystischer Bogen aus dem Drachenholz eines Yama Tsukamis. Das Wissen über seine Bauweise wird nur mündlich weitergegeben.', 'Mystical bow carved from the Dragonwood that grows on Yama Tsukami. Knowledge of its construction is only passed down by word of mouth.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Kut-Ku-Jagdbogen', 'Kut-Ku Stave', 'bow', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"fire"}', '[]', '[]', 'Flammen entfesselnder Jagdbogen aus Yian Kut-Ku-Materialien. Er soll einfach im Gebrauch sein.', 'A Yian Kut-Ku hunting bow that unleashes bolts of fire and has a reputation for easy handling.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Arko Nulo Rouge', 'Arko Nulo Red', 'bow', 1, '{"attack":15,"defense":0,"critical":10,"max_level":3,"element":"fire"}', '[]', '[]', 'Eleganter Bogen aus Bnahabra-Teilen. Seine Pfeile können die Beute verbrennen.', 'An elegant bow made from Bnahabra parts. Arrows fired from it can incinerate prey.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Flammenbogen', 'Flammenbogen', 'bow', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"fire"}', '[]', '[]', 'Ein Bogen aus den Reißzähnen und Flügeln eines Anjanath. Er lässt brandheiße Pfeile regnen.', 'Made of Anjanath fangs and wings, this bow fires a molten rain of arrows.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Flammenweber', 'Weaver of Flame', 'bow', 1, '{"attack":15,"defense":0,"critical":15,"max_level":3,"element":"fire"}', '[]', '[]', 'In Flammen der Absolution gehüllt, versengt der Bogen der wandernden Witwe Fleisch und durchbohrt das Herz. Keiner wird dem Netz der Begierde entkommen.', 'Wreathed in flames of absolution, the Wandering Widow''s bow pierces the heart and sears the flesh. None shall escape its web of desire.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Dunkle Sehne', 'Dark Filament', 'bow', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"fire"}', '[]', '[]', 'Ein Bogen mit brodelnden roten Flammen in seinem Kern. Die Pfeile, die von ihm abgefeuert werden, hüllen ihr Ziel im Höllenfeuer.', 'A bow with seething red flames in its core. Arrows fired from it engulf targets in hellfire.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Aschenzorn', 'Ashen Wrath', 'bow', 1, '{"attack":15,"defense":0,"critical":0,"max_level":3,"element":"fire"}', '[]', '[]', 'Diesem Bogen wohnt ein Inferno inne. Er feuert erbarmungslose Brandpfeile auf den Feind.', 'This bow embodies an inferno, and blasts flaming arrows at enemies without remorse.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Seepferdchen-Harfe', 'Seahorse Harp', 'bow', 1, '{"attack":15,"defense":5,"critical":0,"max_level":3,"element":"water"}', '[]', '[]', 'Göttlicher Bogen. Wyverianische Barden benutzen ihn im Krieg und zum Musizieren.', 'A divine bow. Wyverian minstrels used it for war, and occasionally plucking out catchy tunes.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Schwamm-Bogen', 'Spongia Bow', 'bow', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"water"}', '[]', '[]', 'Aus Königs-Ludroth-Teilen gemacht. Ist die Bogensehne gezogen, quillt Wasser hervor und umgibt den Pfeil.', 'Made from Royal Ludroth parts. When the string is drawn back, water gushes forth and surrounds the arrow.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Blauklingen-Bogen', 'Blue Blade Bow', 'bow', 1, '{"attack":15,"defense":0,"critical":0,"max_level":3,"element":"water"}', '[]', '[]', 'Ein spitzwinkliger Bogen. Ermöglicht den leichten Abschuss von Nicht-Element-Pfeilen.', 'An acutely angled bow. Letting loose some non-elemental shafts is easy with this.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Typ-64-Multibogen', 'Type 64 Multibow', 'bow', 1, '{"attack":35,"defense":20,"critical":0,"max_level":3,"element":"water"}', '[]', '[]', 'Ein hochmoderner Bogen gegen Flugwyvern. Mit seiner Entwicklung haben sich die Handwerker Mühe gegeben.', 'A high-tech bow designed for fighting Flying Wyverns. Artisans invested heavily in its R&D.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Schlammschuss', 'Mud Shot', 'bow', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"water"}', '[]', '[]', 'Bogen aus Almudron-Teilen. Die typische Rundung ist mit Metall verstärkt.', 'Bow made of Almudron parts. Metal braces strengthen the material''s signature curve.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Hydra-Planula', 'Hydra Planula', 'bow', 1, '{"attack":15,"defense":0,"critical":15,"max_level":3,"element":"water"}', '[]', '[]', 'Das schwache Licht in diesem pechschwarzen Namielle-Bogen ist eine Einladung in den Abgrund.', 'The faint light shining in this jet-black Namielle bow is an invitation into the abyss.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Arko Nulo Jaune', 'Arko Nulo Yellow', 'bow', 1, '{"attack":15,"defense":0,"critical":10,"max_level":3,"element":"thunder"}', '[]', '[]', 'Ein eleganter Bogen aus Bnahabra-Teilen. Seine Donnereigenschaften lösen Schock und Erfurcht aus.', 'An elegant bow made from Bnahabra parts. Its electric properties inspire shock and awe.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Kadachi-Bogen', 'Kadachi Strikebow', 'bow', 1, '{"attack":15,"defense":0,"critical":15,"max_level":3,"element":"thunder"}', '[]', '[]', 'Dieser Bogen aus Tobi-Kadachi-Schuppen verstärkt beim Schießen die elektrische Ladung.', 'Made of Tobi-Kadachi scales, this bow amplifies the static produced when firing.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Blitzbogen', 'Lightning Bow', 'bow', 1, '{"attack":15,"defense":0,"critical":20,"max_level":3,"element":"thunder"}', '[]', '[]', 'Ein Wunder der Technik mit mächtigen Pfeilen, die Schuppen durchbohren und Fleisch zerreißen.', 'A marvel of technology featuring powerful arrows to bore through shell and tear through flesh.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Thronräuber-Grollen', 'Usurper''s Rumble', 'bow', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"thunder"}', '[]', '[]', 'Bogen aus dem Panzer eines Monarchen. Seine Pfeile zerfetzen Feinde wie Reißzähne.', 'Bow made from the shell of a peerless monarch. Its arrows sunder enemies like fangs.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Rey Perkonis', 'Rey Perkonis', 'bow', 1, '{"attack":15,"defense":0,"critical":0,"max_level":3,"element":"thunder"}', '[]', '[]', 'Ein von Rey Daus Donner erfüllter Bogen, der seine Ladung auch dann noch behält, nachdem er tausend Blitze entfesselt hat.', 'A bow imbued with Rey Dau''s thunder. Retains a charge even after releasing a thousand bolts.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Blitzschlag-Bogen', 'Thunderbolt Bow', 'bow', 1, '{"attack":15,"defense":0,"critical":0,"max_level":3,"element":"thunder"}', '[]', '[]', 'Narwas Wut, eine Heimsuchung der sterblichen Welt. Durchbohre Feinde mit Blitzkraft.', 'Narwa''s rage visited upon the mortal plane. Pierce foes with lightning force.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Kristallblüte', 'Crystalline Flower', 'bow', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"ice"}', '[]', '[]', 'Mächtiger Bogen mit Kristallbesatz. Die eisig filigranen Pfeile ziehen jedermanns Blicke auf sich.', 'A crystal-encrusted bow. As powerful as its arrows'' icy filigree is distracting.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Arko Nulo Blanc', 'Arko Nulo White', 'bow', 1, '{"attack":15,"defense":0,"critical":10,"max_level":3,"element":"ice"}', '[]', '[]', 'Eleganter Bogen aus Bnahabra-Teilen. Seine Pfeile können die Beute komplett einfrieren.', 'An elegant bow made from Bnahabra parts. Arrows fired from it can freeze prey solid.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Gletscherpfeil', 'Glacial Arrow', 'bow', 1, '{"attack":15,"defense":0,"critical":0,"max_level":3,"element":"ice"}', '[]', '[]', 'Ein Bogen des anmutig schwebenden Legiana. Eine kalte Stille senkt sich herab, wenn die eisigen Pfeile ihre Beute durchbohren.', 'A bow of the gracefully soaring Legiana. As the ice-kissed arrows pierce their quarry, a frosty stillness descends.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Eiswerfer', 'Iceflinger', 'bow', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"ice"}', '[]', '[]', 'Ein eisiger Bogen aus Velkhana-Materialien, der die letzten Schreie seiner Beute in deren Hälsen gefrieren lässt.', 'An icy bow, crafted from Velkhana materials, that freezes the final cries of prey in their throat.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Arko Nulo Noir', 'Arko Nulo Black', 'bow', 1, '{"attack":15,"defense":0,"critical":10,"max_level":3,"element":"dragon"}', '[]', '[]', 'Schwarzer Bnahabra-Bogen mit einer feierlichen Ausstrahlung. Hilfreich bei der Drachenjagd.', 'Ebon Bnahabra bow with an air of solemnity. Aids the user in slaying dragons.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Rebellenbogen', 'Insurgent''s Bow', 'bow', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"dragon"}', '[]', '[]', 'Pfeile, die sich von diesem Bogen lösen, sind so gierig nach Beute wie der schreckliche Dämonjho, dessen Geist in ihm lebt.', 'Arrows loosed from this bow seem as voracious for fresh prey as the terrifying Deviljho, whose spirit is sealed within.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Veldian-Arcum', 'Veldian Arcum', 'bow', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"dragon"}', '[]', '[]', 'Ein Bogen, gefertigt aus Arkveld-Materialien. Findet und durchbohrt Wyvern-Schwachstellen wie vom Träger befohlen.', 'A bow made from Arkveld materials. Its arrows locate vitals as if answering the wielder''s will.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Herzog-Blutflügel', 'Duke''s Bloodwings', 'bow', 1, '{"attack":15,"defense":0,"critical":0,"max_level":3,"element":"dragon"}', '[]', '[]', 'Ein Malzeno-Bogen in Form einer Fledermaus. Sein Pfeil saust wie der Wind durch die mondhelle Nacht.', 'A bat-shaped Malzeno bow, its arrows tear through the moonlit night like the wind.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Eisengewehrlanze', 'Iron Gunlance', 'gunlance', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3}', '[]', '[]', 'Eine Standard-Gewehrlanze, die es dir ermöglicht, zwischen Geschützfeuer und Nahkampfangriffen zu wählen.', 'A standard iron gunlance that gives you the flexibility of choice between gunfire and melee attacks.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Harter Schläger', 'Hard Hitter', 'gunlance', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"status":"poison","status_rate":12}', '[]', '[]', 'Aus Gypceros-Leder und feinem Erz gefertigt. Enthält tödliches Gift, das der bedauernswerten Beute große Qualen bereitet.', 'Made from Gypceros leather and fine ore. Contains lethal venom, which causes great agony to the unfortunate prey.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Pukei-Gewehrlanze', 'Pukei Gunlance', 'gunlance', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"status":"poison","status_rate":12}', '[]', '[]', 'Diese Gewehrlanze aus Pukei-Pukei-Teilen kommt mit einem Schild in Tarnfarben.', 'Made from Pukei-Pukei parts, this gunlance sports a shield with camouflage colors.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Barroth-Lader', 'Barroth Loader', 'gunlance', 1, '{"attack":35,"defense":15,"critical":0,"max_level":3}', '[]', '[]', 'Weist überwältigende Fern- und Nahkampfangriffskraft auf. Ihre Robustheit kann es mit der felsigen Haut des Barroth aufnehmen.', 'Boasts overwhelming fire and melee power, and sturdiness to rival that of the Barroth''s rocky hide.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Panzer-Kanonenvogel', 'Shell Gunbird', 'gunlance', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"status":"blast","status_rate":8}', '[]', '[]', 'Aus geschichteten Nerscylla-Teilen gefertigt. Das zerbrechliche Aussehen täuscht über ihre wahre Macht hinweg.', 'Made from layered Nerscylla parts. The fragile appearance belies its true power.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Fiore Nulo Vert', 'Fiore Nulo Green', 'gunlance', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"status":"sleep","status_rate":12}', '[]', '[]', 'Die dornengleiche Spitze der Bnahabra-Gewehrlanze kann mit einem einzigen Stich lähmen.', 'The thorn-like tip of this Bnahabra gunlance can cause paralysis with a single thrust.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Popcornkanone', 'Cornpopper', 'gunlance', 1, '{"attack":35,"defense":10,"critical":0,"max_level":3}', '[]', '[]', 'Von einem Handwerker entworfen, der sich womöglich nach einem Bauernleben sehnte. Mächtiger, als du ihr zutrauen würdest.', 'Designed by a craftsman who perhaps hankered to be a farmer. More powerful than you''d give it credit for.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Tigerstoß', 'Tiger Blast', 'gunlance', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3}', '[]', '[]', 'Eine Gewehrlanze aus Tigrex-Materialien. Ihr Brüllen lehrt Wyvern die Furcht.', 'A gunlance made from Tigrex materials. Its roar sends wyverns running to roost.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Finstergewehrlanze', 'Sinister Gunlance', 'gunlance', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"status":"paralysis","status_rate":10}', '[]', '[]', 'Der Klang dieser Gewehrlanze erinnert an den Schrei des Tückischen Wyvern.', 'The sound of this gunlance is reminiscent of the roar of the Wyvern of Malice.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Gold-Drachenholz-Gewehrlanze', 'Gold Dragonwood Gunlance', 'gunlance', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"status":"sleep","status_rate":8}', '[]', '[]', 'Aus Drachenholz nach geheimer Wyverianer-Methode gefertigt. Aufgrund des Designs lässt es sich nicht gut am Rücken verstauen.', 'Made of Dragonwood with secret Wyverian methods. Due to its design, it doesn''t fold when stowed on your back.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Fiore Nulo Rouge', 'Fiore Nulo Red', 'gunlance', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"fire"}', '[]', '[]', 'Der kastanienrote Kolben der Bnahabra-Gewehrlanze erinnert an Blumenknospen.', 'The maroon barrel on this Bnahabra gunlance calls to mind flower buds.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Aknosom-Gewehrlanze', 'Aknosom Gunlance', 'gunlance', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"fire"}', '[]', '[]', 'Elegante Gewehrlanze aus Aknosom-Teilen mit fortschrittlichem Kühlsystem.', 'An elegant gunlance made from Aknosom parts. It has an advanced cooling system.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Prinzessinnenzier', 'Princess Panoply', 'gunlance', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"fire","status":"poison","status_rate":8}', '[]', '[]', 'Eine Gewehrlanze mit grünen Königin-Schuppen. Verschießt Gift, tränkt die Erde mit dem Blut der Feinde.', 'A gunlance covered in the Queen''s green scales. Firing poisonous shots, it stains the earth with enemy blood.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Dios-Gewehrlanze', 'Dios Gunlance', 'gunlance', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"fire","status":"paralysis","status_rate":8}', '[]', '[]', 'Eine Gewehrlanze, die mit leuchtenden Brachydios-Schleimpilzen gefüllt wurde. Ihre Macht sprengt die menschliche Vorstellungskraft.', 'A gunlance filled with glowing Brachydios slime mold. Its power is beyond human comprehension.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Ajara-Feuerspieß', 'Ajara Gunpike', 'gunlance', 1, '{"attack":15,"defense":0,"critical":10,"max_level":3,"element":"fire","status":"paralysis","status_rate":8}', '[]', '[]', 'Eine Ajarakan-Gewehrlanze, deren mächtige Hitzestöße alles aus ihrem Weg räumen.', 'An Ajarakan gunlance that produces high-powered blasts of heat to instantly remove all in its path.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Rosenkanone', 'Rosenkanone', 'gunlance', 1, '{"attack":15,"defense":0,"critical":10,"max_level":3,"element":"fire","status":"poison","status_rate":8}', '[]', '[]', 'Espinas-Gewehrlanze. Feurig brüllend legt sie alle um, die ihr Revier beflecken.', 'Espinas gunlance. Its fiery "roar" blows away anything that defiles its territory.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Weiße Gewehrlanze', 'White Gunlance', 'gunlance', 1, '{"attack":35,"defense":20,"critical":0,"max_level":3,"element":"fire","status":"poison","status_rate":8}', '[]', '[]', 'Sowohl die Lanze als auch der Schild sind aus Gravios-Schuppen gefertigt. Ihre Größe zieht sofort alle Blicke auf sich.', 'Both the lance and shield are crafted from Gravios scales. Their great size immediately draws the eye.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Ludroth-Harpune', 'Ludroth Harpoon', 'gunlance', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"water"}', '[]', '[]', 'Zur Monsterjagd umfunktioniertes Anglerwerkzeug. Die Spitze liegt im Kampf frei.', 'A fishing tool redesigned for monster hunting. The tip is exposed in combat.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Typ-62-Sturmlanze', 'Type 62 Stormlance', 'gunlance', 1, '{"attack":35,"defense":20,"critical":0,"max_level":3,"element":"water"}', '[]', '[]', 'Furchterregende Gewehrlanze mit geheimster Technologie. Zum Erlegen von Wyvern konstruiert.', 'A fearsome gunlance made with top-secret artisinal technology. It was designed to slay wyverns.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Almudron-Gewehrlanze', 'Almudron Gunlance', 'gunlance', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"water"}', '[]', '[]', 'Gewehrlanze aus Almudron-Teilen. Selbst im Schlamm noch zuverlässig zu handhaben.', 'A gunlance made of Almudron parts. It handles steadily, even on the muddiest ground.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Meeresfischer', 'Marine Fisher', 'gunlance', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"water"}', '[]', '[]', 'Eine scharfzackige Plesioth-Gewehrlanze, die Wasserstrahlen verschießt. Sie blenden die Beute, die bald darauf verendet.', 'A sharp-pronged Plesioth gunlance that shoots jets of water, blinding the prey, which then meets its demise.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Hydra-Ephyra', 'Hydra Ephyra', 'gunlance', 1, '{"attack":15,"defense":0,"critical":15,"max_level":3,"element":"water"}', '[]', '[]', 'Die Dunkelheit auf der Klinge dieser Namielle-Gewehrlanze reißt die Beute in den Abgrund.', 'Endless darkness dances on the blade of this Namielle gunlance, guiding prey into the abyss.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Kadachi-Kanone', 'Kadachi Striker', 'gunlance', 1, '{"attack":15,"defense":0,"critical":15,"max_level":3,"element":"thunder"}', '[]', '[]', 'Geschaffen aus Tobi-Kadachi Schuppen. Treffer dieser Gewehrlanze bewirken eine elektrische Entladung in der Beute.', 'Made of Tobi-Kadachi scales. Every hit of this gunlance channels an electrical charge into your prey.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Roter Generator', 'Red Generator', 'gunlance', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"thunder"}', '[]', '[]', 'Gewehrlanze mit mächtigem Stromspeicher. Erinnert kaum an ihre Khezu-Ursprünge.', 'A gunlance with a powerful electric reservoir. Hardly resembles its Khezu origins.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Thronräuber-Gebrüll', 'Usurper''s Roar', 'gunlance', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"thunder"}', '[]', '[]', 'Gewehrlanze mit der Macht eines Monarchen. Ihr Donnern kündet vom Kommen des neuen Eroberers.', 'A gunlance with the power of a monarch. Its mighty roar heralds the world conqueror.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Lagia-Sprenger', 'Lagia Burst', 'gunlance', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"thunder"}', '[]', '[]', 'Wie ein Strudel entfesselt die Lagiacrus-Gewehrlanze elektrische Ladungen, die deine Beute in spiralförmigen Bewegungen verfolgt.', 'Twisted like a whirlpool, the Lagiacrus gunlance unleashes electric charges that spiral after your prey.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Kamak-Gewehrlanze', 'Kamak Gunlance', 'gunlance', 1, '{"attack":35,"defense":20,"critical":0,"max_level":3,"element":"ice"}', '[]', '[]', 'Ein Kunstwerk, geschaffen für Felynen, die um das Ende des Winters trauern.', 'A fine work of art made for Felynes bummed about winter ending.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Höllenstich', 'Hellsting', 'gunlance', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"ice"}', '[]', '[]', 'Eine Gewehrlanze, die durch ihre Blangonga-Teile ernsthafte Kälte verursachen kann.', 'A gunlance able to deal some serious cold with the help of its Blangonga parts.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Zwillingsreißzahn', 'Twinfang', 'gunlance', 1, '{"attack":15,"defense":0,"critical":15,"max_level":3,"element":"ice"}', '[]', '[]', 'Gewehrlanze aus zwei eisigen Barioth-Reißzähnen. Trifft Beute wie ein Schneesturm.', 'A gunlance made from the two icy fangs of a Barioth. Blasts prey like a blizzard.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Frostmond-Gewehrlanze', 'Frostmoon Gunlance', 'gunlance', 1, '{"attack":15,"defense":0,"critical":0,"max_level":3,"element":"ice"}', '[]', '[]', 'Der gefrorene Lauf dieser Lunagaron-Gewehrlanze streut bei jedem Schuss mondbeschienene Eissplitter.', 'This Lunagaron gunlance''s frozen barrel scatters moonlit ice shards with every shot.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Fiore Nulo Noir', 'Fiore Nulo Black', 'gunlance', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"dragon"}', '[]', '[]', 'Diese schwarze Gewehrlanze wurde speziell aus Bnahabra-Teilen gemacht, die für den Kampf gegen Drachen geeignet sind.', 'This black gunlance made from Bnahabra parts was designed to be especially effective against dragons.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Gefräßige Gewehrlanze', 'Ravenous Gunlance', 'gunlance', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"dragon"}', '[]', '[]', 'Eine Gewehrlanze, die den furchterregenden Dämonjho einschließt. Sollte das Siegel brechen, wird die Welt ihr Ende finden.', 'A gunlance that seals the terrifying Deviljho. Should the seal be broken, the world shall meet its end.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Veldian Hasta', 'Veldian Hasta', 'gunlance', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"dragon"}', '[]', '[]', 'Eine Gewehrlanze aus Arkveld-Materialien. Sie brachte einst einen hochmütigen Wyvern zu Fall, der sich gegen die Natur auflehnte.', 'A gunlance made from Arkveld materials. With it, a haughty wyvern that rose against nature was returned to the earth.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Ranger-Rüstung', 'Ranger Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"weak"}}', '[]', '[]', 'In jeder Umgebung einfach zu nutzende Rüstung für Ranger. Das Wappen steht für die Treue zu Azuria.', 'Armor specially made for Rangers to be functional in any environment. The emblem proves one''s allegiance to Azuria.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Jäger-Rüstung', 'Hunter Armor', 'armor', 1, '{"max_level":3,"element_resist":{"dragon":"weak"}}', '[]', '[]', 'Universell von Jägern getragene Rüstung. Aus starken Metallen und robuster, doch biegsamer Haut gemacht.', 'Armor worn universally by Hunters. Made with strong metals and sturdy but pliable hide.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Knochen-Rüstung', 'Bone Armor', 'armor', 1, '{"max_level":3,"element_resist":{"ice":"weak"}}', '[]', '[]', 'Rüstung aus einem harten Knochen. Weist trotz der wilden Designwahl eine hohe Verteidigungsstufe auf.', 'Armor made from tough bone. Boasts a high defensive power despite the wild design choices.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Leder-Rüstung', 'Leather Armor', 'armor', 1, '{"max_level":3,"element_resist":{"thunder":"weak"}}', '[]', '[]', 'Rüstung aus leichten Materialien auf Lederbasis. Reagiert flexibel auf jede Situation.', 'Armor made from light materials using leather as a base. Responds flexibly to any situation.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Bnahabra-Rüstung', 'Bnahabra Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"very_weak","non_elemental":"weak"}}', '[]', '[]', 'Hochwertige Rüstung aus einem Neopteron. So bequem und nicht schwerer als ein Schmetterling, der auf deiner Schulter landet.', 'High-quality armor made from a Neopteron. The comfort of its fit feels no heavier than a butterfly landing on one''s shoulder.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Paolumu-Rüstung', 'Lumu Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"strong_resist","thunder":"resist"}}', '[]', '[]', 'Als Nachbildung des flauschigen weißen Paolumu gefertigt, inklusive einem süßen Hut, der dem aufgeblasenen Monster ähnelt.', 'Armor made to resemble the fluffy white Paolumu, including a cute hat that looks like the monster in its inflated state.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Chatacabra-Rüstung', 'Chatacabra Armor', 'armor', 1, '{"max_level":3,"element_resist":{"ice":"strong_resist","non_elemental":"resist"}}', '[]', '[]', 'Rüstung aus Chatacabra-Teilen. Sie wurde speziell für das Jagen in der Wüste hergestellt.', 'Armor made from Chatacabra parts. The design is specially tailored for desert hunting.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Kut-Ku-Rüstung', 'Kut-Ku Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"resist","dragon":"strong_resist"}}', '[]', '[]', 'Farbenfrohe Rüstung aus dem stacheligen Rückenpanzer eines Yian Kut-Ku. Dieser macht sie außergewöhnlich robust.', 'Vividly colored armor made from a Yian Kut-Ku. The sharply- spiked carapace allows for an exceptionally sturdy finish.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Kut-Ku-U-Rüstung', 'Kut-Ku U Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"resist","thunder":"strong_resist"}}', '[]', '[]', 'Rüstung aus einem Blauen Yian Kut-Ku. Die einmalige Färbung der Rüstung ist Beweis für die Siege in einem Leben voller Kämpfe.', 'Armor made from a Blue Yian Kut-Ku. The unique coloring of the armor is proof of its victories in a life of battle.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Gypceros-Rüstung', 'Gypceros Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"strong_resist","ice":"resist"}}', '[]', '[]', 'Rüstung aus der Gummihaut eines Gypceros. Flexible Materialien geben der Konstruktion eine starke Verteidigung.', 'Armor made using the rubbery skin of a Gypceros. The flexible materials used in its construction allow for a strong defense.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Gypceros-U-Rüstung', 'Gypceros U Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"strong_resist","ice":"resist"}}', '[]', '[]', 'Rüstung aus der Haut eines Lila Gypceros. Die dicke Gummihaut wehrt alle Angriffe ab.', 'Armor made from the hide of a Purple Gypceros. The thick rubbery skin repels all attacks.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Ludroth-Rüstung', 'Ludroth Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"strong_resist","thunder":"resist"}}', '[]', '[]', 'Luxuriöse Rüstung aus der schwammigen Mähne eines Königs- Ludroth. Leicht, doch exzellent zum Absorbieren von Stößen.', 'Luxurious armor made from the sponge-like mane of the Royal Ludroth. Light, but excels at absorbing heavy impacts.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Ludroth-U-Rüstung', 'Ludroth U Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"strong_resist","thunder":"resist"}}', '[]', '[]', 'Rüstung, gefärbt mit dem Gift des Lila Ludroth. Trotz ihrer Dicke gewährt ihre Schwammigkeit viel Bewegungsfreiheit.', 'Armor dyed purple with Purple Ludroth poison. Its spongy materials allow for freedom of movement despite its thickness.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Nerscylla-Rüstung', 'Nerscylla Armor', 'armor', 1, '{"max_level":3,"element_resist":{"ice":"strong_resist","non_elemental":"resist"}}', '[]', '[]', 'Rüstung aus einem Nerscylla. Ihr präzises Design und die geschickte Struktur sorgen für hochrangige Verteidigung.', 'Armor made from a Nerscylla. Its precise design and skilled construction allow for strong defensive properties.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Nerscylla-U-Rüstung', 'Nerscylla U Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"very_weak","thunder":"weak","dragon":"strong_resist","non_elemental":"resist"}}', '[]', '[]', 'Rüstung aus einem Getarnten Nerscylla. Lockt Beute in seine wunderschöne dämmrige Dunkelheit.', 'Armor made from a Shrouded Nerscylla. Beckons prey into its beautiful twilight darkness.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Kadachi-Rüstung', 'Kadachi Armor', 'armor', 1, '{"max_level":3,"element_resist":{"thunder":"strong_resist","ice":"resist"}}', '[]', '[]', 'Rüstung aus den blassblauen Schuppen und dem weißen Fell eines Tobi-Kadachi. Sein Helm blockiert dir niemals den Ausblick!', 'Armor made from the pale-blue scales and white fur of a Tobi-Kadachi. Enjoy the view—its helmet won''t block your vision.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Plesioth-Rüstung', 'Plesioth Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"very_weak","thunder":"resist","ice":"strong_resist","dragon":"weak"}}', '[]', '[]', 'Plesioth-Schuppen wurden in diese enganliegende Rüstung genäht. Hält mehr aus, als man erwartet.', 'Plesioth scales have been sewn into this tight-fitting armor. It''s sturdier than it appears.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Plesioth-U-Rüstung', 'Plesioth U Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"very_weak","thunder":"resist","ice":"strong_resist","dragon":"weak"}}', '[]', '[]', 'Rüstung aus Grüner-Plesioth-Schuppen. Sieht so bedrohend undurchdringbar aus, dass sogar Monsties unruhig werden.', 'Armor made from Green Plesioth scales. Looks so intimidatingly impenetrable, even Monsties feel uneasy around it.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Anjanath-Rüstung', 'Anja Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"resist","thunder":"strong_resist"}}', '[]', '[]', 'Rüstung, die reichlich mit feuerresistenter Anjanath-Haut verziert wurde.', 'Armor richly embellished with the fire-resistant hide of an Anjanath.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('FulgurAnjanathRüstng', 'Fulgur Anja Armor', 'armor', 1, '{"max_level":3,"element_resist":{"thunder":"very_weak","ice":"resist","dragon":"strong_resist","non_elemental":"weak"}}', '[]', '[]', 'Fulgur-Anjanath-Rüstung mit markantem Streifenmuster auf grauem Hintergrund, wie Blitze über einer gefrorenen Ödnis.', 'Fulgur Anjanath armor. Sports a distinctive striped pattern on a gray background, like lightning against frozen wasteland.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Brachydios-Rüstung', 'Brachydios Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"resist","thunder":"very_weak","dragon":"strong_resist","non_elemental":"weak"}}', '[]', '[]', 'Rüstung, welche die enorme Kraft eines Brachydios enthält. Sie verfügt über die Kraft, Explosionen standzuhalten.', 'Armor containing the enormous power of a Brachydios. Holds the strength to withstand explosions.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Espinas-Rüstung', 'Espinas Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"resist","ice":"weak","dragon":"strong_resist","non_elemental":"very_weak"}}', '[]', '[]', 'Espinas-Rüstung umhüllt von einem tödlichem Gestank. Ihr andauernder Gestank schärft die Sinne ihres Trägers.', 'Espinas armor wreathed in a deadly miasma. Constant exposure to these fumes sharpens the wearer''s senses.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Rathian-Rüstung', 'Rathian Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"resist","non_elemental":"strong_resist"}}', '[]', '[]', 'Rüstung aus der Königin des Landes, einer Rathian. Bedeckt mit Schuppen, die für gängige Metalle undurchlässig sind.', 'Armor made from the Queen of the Land, a Rathian. Covered in scales that are impervious to common metals.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Rathianherz-Rüst.', 'Rath Heart Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"resist","thunder":"weak","ice":"very_weak","non_elemental":"strong_resist"}}', '[]', '[]', 'Rüstung, die an die fallenden Blüten des Kirschbaums erinnert. Auch Monster werden durch ihre Schönheit betört.', 'Armor reminiscent of the falling petals of the cherry blossom tree. Its beauty will draw even the eyes of monsters.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Lagiacrus-Rüstung', 'Lagiacrus Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"strong_resist","thunder":"weak","ice":"resist","non_elemental":"very_weak"}}', '[]', '[]', 'Rüstung aus einem Lagiacrus. Ihr Tiefes Blau beschwört die Tie- fen des Meeres und baut sanft den Kampfwillen des Trägers auf.', 'Armor made from the Lord of the Seas, Lagiacrus. The blue which evokes the sea''s depths will softly build the will to fight.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Lagiacrus-U-Rüstung', 'Lagiacrus U Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"strong_resist","thunder":"weak","ice":"resist","non_elemental":"very_weak"}}', '[]', '[]', 'Rüstung aus einem glänzenden Elfenbein-Lagiacrus. Ihre erstaunliche weiße Farbe ergreift die Seele.', 'Armor made from the brilliant Ivory Lagiacrus. Its startling white coloring takes hold of the soul.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Astalos-Rüstung', 'Astalos Armor', 'armor', 1, '{"max_level":3,"element_resist":{"thunder":"very_weak","ice":"resist","dragon":"strong_resist","non_elemental":"weak"}}', '[]', '[]', 'Astalos-Rüstung mit scharfen Stacheln und pulsierendem Licht. Gib deine Reinheit auf, um ihren dunklen Segen zu erhalten.', 'Astalos armor bristling with sharp spikes and pulsating light. Give up your purity to earn its dark blessing.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Legierungs-Rüstung', 'Alloy Armor', 'armor', 1, '{"max_level":3,"element_resist":{"fire":"weak","ice":"very_weak"}}', '[]', '[]', 'Rüstung aus hochwertigem Erz. Speziell für Funktionalität entworfen, ohne Firlefanz.', 'Armor made from high-quality ore. Designed for functionality, free from superfluous additions.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Edel-Rüstung', 'Edel Armor', 'armor', 1, '{"max_level":3,"element_resist":{"thunder":"resist","ice":"strong_resist"}}', '[]', '[]', 'Sorgfältig gewobene Rüstung, mit der man aufblüht. Ihre Eleganz verbirgt eine hohe Verteidigungskraft.', 'Any situation will come up roses while sporting this meticulously woven armor. The elegant appearance belies a durable defense.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Yukumo-Rüstung', 'Yukumo Armor', 'armor', 1, '{"max_level":3,"element_resist":{"ice":"weak"}}', '[]', '[]', 'Von Leuten aus dem fernen Osten getragene Rüstung. Dank des Fokus auf Bewegungsfreiheit, ist sie vielseitig anwendbar.', 'Armor worn by the people of lands far to the east. Due to its focus on maneuverability, this armor sees use in a variety of situations.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Izuchi-Rüstung', 'Izuchi Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"weak","ice":"very_weak"}}', '[]', '[]', 'Groß-Izuchi-Rüstung, die einst einem legendären Dieb gehörte. Es heißt, ihr Träger kann Windböen heraufbeschwören.', 'Great Izuchi armor that was once prized by a legendary thief. Some say its wearer can conjure gusts of wind at will.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Arzuros-Rüstung', 'Arzuros Armor', 'armor', 1, '{"max_level":3,"element_resist":{"fire":"weak","water":"very_weak"}}', '[]', '[]', 'Rüstung, die aus Arzuros-Materialien gefertigt wurde. Ihr kühnes Design nutzt die Panzerung der Arzuros-Unterarme, die Armschienen ähnelt.', 'Armor made using materials from an Arzuros. The audacious design utilizes the vambrace-like armor of the Arzuros'' forearms.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Tetranadon-Rüstung', 'Tetranadon Armor', 'armor', 1, '{"max_level":3,"element_resist":{"thunder":"resist","ice":"strong_resist"}}', '[]', '[]', 'Rüstung aus robusten Tetranadon-Materialien. Erlaubt dem Träger die Anpassung an die Umgebung.', 'Armor made from bulky Tetranadon materials. Enables the wearer to adapt to a variety of environments, much like the monster itself.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Bishaten-Rüstung', 'Bishaten Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"very_weak","thunder":"weak","dragon":"strong_resist","non_elemental":"resist"}}', '[]', '[]', 'Bishaten-Rüstung, die der Kutte eines Mönches ähnelt. Soll den Träger vor Unheil schützen.', 'Bishaten armor modeled after the robes of ascetics. Said to guide the wearer away from misfortune.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Bishaten-U-Rüstung', 'Bishaten U Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"resist","ice":"very_weak","dragon":"strong_resist","non_elemental":"weak"}}', '[]', '[]', 'Blut-Bishaten-Rüstung, als Lohn nach einer strengen Prüfung. Mit ihr erkennt der Träger Böses und beseitigt Unreinheiten.', 'Blood Orange Bishaten armor given to those who have undergone a trial of self-discipline. Allows the wearer to find evil and cleanse impurity.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Pukei-Pukei-Rüstung', 'Pukei-Pukei Armor', 'armor', 1, '{"max_level":3,"element_resist":{"thunder":"resist","ice":"strong_resist"}}', '[]', '[]', 'Mache dich mit dieser Pukei-Pukei-Rüstung zu einem verhülltem Mysterium. Perfekt für schnelle Bewegungen und das Schleichen durch hohes Gras.', 'Cloak yourself in mystery with this Pukei-Pukei armor. Perfect for moving quickly and sneaking up on prey in tall grass.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Somnacanth-Rüstung', 'Somnacanth Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"very_weak","thunder":"resist","ice":"strong_resist","non_elemental":"weak"}}', '[]', '[]', 'Rüstung aus einem Somnacanth. Wer sie anblickt, verliert sich in ihrer hypnotisierenden Aura.', 'Armor made from a Somnacanth. Those who gaze upon it find themselves befuddled by its hypnotic aura.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Somnacanth-U-Rüstung', 'Somnacanth U Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"strong_resist","ice":"very_weak","dragon":"resist","non_elemental":"weak"}}', '[]', '[]', 'Auroracanth-Rüstung, die bittere Kälte ausstrahlt. Nur eine kurze Berührung lässt jeden sofort erfrieren.', 'Aurora Somnacanth armor that emanates a bitter chill. A single touch will instantly freeze the unwary.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Aknosom-Rüstung', 'Aknosom Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"resist","thunder":"strong_resist"}}', '[]', '[]', 'Ritterliche Rüstung aus Teilen eines Aknosom. Ihr elegantes Design strahlt galante Anmut aus.', 'Knightly armor intricately crafted from Aknosom parts. Its elegant design exudes chivalrous grace.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Khezu-Rüstung', 'Khezu Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"strong_resist","ice":"resist","dragon":"weak"}}', '[]', '[]', 'Rüstung aus dem glänzend perlgrauen Pelz eines Khezu. Sehr weich und liegt eng am Körper an.', 'Armor fashioned from the shining pearl-gray pelt of a Khezu. Textured close to the skin for a soft touch.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Khezu-U-Rüstung', 'Khezu U Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"weak","thunder":"strong_resist","ice":"resist"}}', '[]', '[]', 'Rüstung im satten Karmesin des Roten Khezu. Lockt mit einer eigenartigen Ausstrahlung.', 'Armor overflowing with the rich crimson of a Red Khezu. Beckons with a strange allure.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Garuga-Rüstung', 'Garuga Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"resist","thunder":"strong_resist","ice":"weak","dragon":"very_weak"}}', '[]', '[]', 'Rüstung, für welche die unheilvolle Macht des Yian Garuga genutzt wurde. Jeder Schlag stärkt sie.', 'Armor made utilizing the sinister power of the Yian Garuga. Strengthens under every blow.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Golm-Rüstung', 'Golm Armor', 'armor', 1, '{"max_level":3,"element_resist":{"fire":"weak","water":"very_weak","thunder":"resist","ice":"very_weak"}}', '[]', '[]', 'Garangolm-Rüstung eines Waldkriegers. Nur jemand mit reinem Herzen kann sie tragen.', 'Garangolm armor held in high esteem by woodland warriors. Only the pure of heart are worthy of wearing it.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Regios-Rüstung', 'Regios Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"resist","ice":"strong_resist","dragon":"very_weak","non_elemental":"weak"}}', '[]', '[]', 'Goldene Rüstung aus einem Seregios. Mit tausend Klingen bedeckt schneidet sie jeden, der sie unvorsichtig berührt.', 'Golden armor made from a Seregios. Clad in a thousand blades, it cuts any who touch it carelessly.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Vangis-Rüstung', 'Vangis Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"weak","thunder":"weak","ice":"strong_resist","dragon":"resist","non_elemental":"strong_resist"}}', '[]', '[]', 'Aus den noch pulsierenden Teilen eines Dämonjho gemacht. Mit dicken, starken Schuppen bedeckt.', 'Made from the still pulsating parts of a Deviljho. Covered with thick and strong scales.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Nargacuga-Rüstung', 'Nargacuga Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"very_weak","thunder":"weak","ice":"strong_resist","dragon":"resist"}}', '[]', '[]', 'Rüstung aus einem Nargacuga, im Dunkel der Mitternacht geboren. Schwarzes Material verschleiert den Träger in den Schatten.', 'Armor made from a Nargacuga, born of midnight''s darkness. Its black cloth melts into the shadows, hiding a wearer''s presence.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Nargacuga-U-Rüstung', 'Nargacuga U Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"very_weak","thunder":"weak","ice":"strong_resist","dragon":"resist"}}', '[]', '[]', 'Rüstung aus einem Grünen Nargacuga, im tiefen Wald geboren. Trä- ger verschmelzen mit der Umgebung beim Heranpirschen an Beute.', 'Armor made from a Green Nargacuga, born from the deep forest. Blends into its surroundings as wearers close in on their prey.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Mizutsune-Rüstung', 'Mizutsune Armor', 'armor', 1, '{"max_level":3,"element_resist":{"thunder":"resist","ice":"strong_resist","dragon":"weak","non_elemental":"very_weak"}}', '[]', '[]', 'Rüstung aus dem himmlischen Mizutsune. Die Sage eines Mannes, so bezaubert, dass er seine wahre Braut verkannte, liegt zugrunde.', 'Armor made from the ethereal Mizutsune. Linked to the tale of a man who, so captivated, was blind to the true form of his bride.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Azur-Rüstung', 'Azure Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"resist","thunder":"very_weak","dragon":"strong_resist","non_elemental":"weak"}}', '[]', '[]', 'Rüstung, speziell hergestellt in einer entfernten Werkstatt. In ihr ist ein Geheimnis verborgen.', 'Armor developed in a distant land using novel forging techniques. Its capabilities are a mystery.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Wächter-Rüstung', 'Guardian Armor', 'armor', 1, '{"max_level":3,"element_resist":{"fire":"weak"}}', '[]', '[]', 'Rüstung von Rittern, die ihre Stadt verteidigen. Speziell angefertigt, um Verteidigung und Beweglichkeit zu stärken.', 'Armor bestowed upon knights who are sworn to defend their city. Masterfully crafted, it provides excellent defense and mobility.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Aelucanth-Rüstung', 'Aelucanth Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"strong_resist","ice":"resist","dragon":"very_weak","non_elemental":"weak"}}', '[]', '[]', 'Rüstung, die ihren Träger zum Herrscher der Insektenwelt macht. Jedes Insekt muss sich vor ihr verbeugen.', 'Armor symbolizing dominion over all insect-kind. Every bug must bow before nature''s champion.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Rhopessa-Rüstung', 'Rhopessa Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"strong_resist","ice":"resist","dragon":"very_weak","non_elemental":"weak"}}', '[]', '[]', 'Rüstung aus Insektenteilen. Ihr majestätisches Aussehen beeindruckt jeden.', 'Armor made from insect parts. Its refined majesty is guaranteed to make an impression.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Kululu-Rüstung', 'Kululu Armor', 'armor', 1, '{"max_level":3,"element_resist":{"thunder":"very_weak","dragon":"weak"}}', '[]', '[]', 'Rüstung, die für heiße trockene Umgebungen angepasst wurde. Mit großen Kulu-Ya-Ku-Federn verziert.', 'Armor optimized for hot and arid environments, decorated with large Kulu-Ya-Ku feathers.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Barroth-Rüstung', 'Barroth Armor', 'armor', 1, '{"max_level":3,"element_resist":{"fire":"resist","water":"strong_resist","thunder":"very_weak","ice":"weak"}}', '[]', '[]', 'Zäh. Sehr zäh. Aus einem Barroth mit Fokus auf Zähigkeit gemacht. Könnte auch eine Festung sein. Eine stabile.', 'Tough. Very tough. Made from a Barroth with nothing but toughness in mind. May as well be a fortress. A tough one.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Barroth-U-Rüstung', 'Barroth U Armor', 'armor', 1, '{"max_level":3,"element_resist":{"fire":"weak","water":"strong_resist","ice":"very_weak","dragon":"resist"}}', '[]', '[]', 'Rüstung aus einem Jade-Barroth. Ihr enormer eisbergartiger Rückenpanzer sorgt für unvergleichliche Robustheit.', 'Armor made from a Jade Barroth. Its vast, iceberg-like carapace allows for unparalleled toughness.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Ceanataur-Rüstung', 'Ceanataur Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"very_weak","thunder":"weak","ice":"strong_resist","non_elemental":"resist"}}', '[]', '[]', 'Rüstung aus einem harten Shogun-Ceanataur-Panzer. Hervorstehende Klingen können einen unvorsichtigen Träger verletzen.', 'Armor made from a Shogun Ceanataur''s hardened carapace. The bladed protrusions can injure a careless wearer.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Almudron-Rüstung', 'Almudron Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"strong_resist","thunder":"resist","ice":"weak","dragon":"very_weak"}}', '[]', '[]', 'Rüstung speziell hergestellt aus Almudron-Materialien. Trotz ihrer Robustheit ist sie sehr leicht.', 'Armor expertly forged from Almudron materials to retain its sturdiness while being extremely lightweight.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Ajarakan-Rüstung', 'Ajarakan Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"resist","thunder":"strong_resist","ice":"weak","dragon":"very_weak"}}', '[]', '[]', 'Ajarakan-Rüstung. Die Hitze ihrer Flammen brennt ihre Beute endgültig nieder.', 'Ajarakan armor. The heat of its flames warns prey of their final immolation.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Odogaron-Rüstung', 'Odogaron Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"resist","thunder":"weak","ice":"very_weak","dragon":"strong_resist"}}', '[]', '[]', 'Blutrote Odogaron-Rüstung. Lässt den Träger rasend nach seiner Beute jagen.', 'Blood-red Odogaron armor. Drives any who wear it into a frenzied hunt for prey.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Vulkan-Rüstung', 'Death Garon Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"very_weak","thunder":"very_weak","ice":"very_weak","dragon":"very_weak","non_elemental":"resist"}}', '[]', '[]', 'Rüstung aus Vulkan-Odogaron. Erweckt die grausame Natur, die im Träger schlummert.', 'Armor crafted from Ebony Odogaron parts. Awakens a latent thirst for cruelty within the wearer.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Rakna-Rüstung', 'Rakna Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"resist","thunder":"very_weak","dragon":"strong_resist","non_elemental":"weak"}}', '[]', '[]', 'Wie die Hauptfigur einer Liebestragödie betört diese Rakna-Kadaki-Rüstung jeden, der sie sieht.', 'Like a character from a tragic love story, this Rakna-Kadaki armor is said to beguile all who lay eyes upon it.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Glavenus-Rüstung', 'Glavenus Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"resist","thunder":"strong_resist","ice":"weak","dragon":"very_weak"}}', '[]', '[]', 'Schmücke dich mit dieser feurigen Haut, frisch einem Glavenus abgezogen. Aber Achtung: Diese Rüstung dient nur starken Kämpferseelen.', 'Adorn yourself in fiery skin fresh off a Glavenus'' back. But beware—this armor only aids those with a strong fighting spirit.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Diablos-Rüstung', 'Diablos Armor', 'armor', 1, '{"max_level":3,"element_resist":{"fire":"weak","water":"resist","thunder":"very_weak","dragon":"strong_resist"}}', '[]', '[]', 'Rüstung aus dem Rückenpanzer eines Diablos, dem Tyrannen der Wüste. Der Anblick der Hörner lässt Monster vor Furcht erbeben.', 'Armor made from the carapace of Diablos, tyrant of the desert. The sight of the horns will cause monsters to tremble in fear.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Diablos-Nero-Rüstung', 'Diablos Nero Armor', 'armor', 1, '{"max_level":3,"element_resist":{"fire":"weak","water":"resist","thunder":"very_weak","dragon":"strong_resist"}}', '[]', '[]', 'Einzigartige Rüstung aus einer Schwarzen Diablos. Wer ihre gewaltige Form sieht, erbebt vor Furcht.', 'Unparalleled armor made from a Black Diablos. All who gaze upon its towering form quake in terror.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Gravios-Rüstung', 'Gravios Armor', 'armor', 1, '{"max_level":3,"element_resist":{"fire":"weak","water":"resist","thunder":"strong_resist","non_elemental":"very_weak"}}', '[]', '[]', 'Rüstung aus einem Gravios-Rückenpanzer. Kann sogar Lava widerstehen. Fühlt sich schwer genug an, um die Erde zu spalten.', 'Armor made from the carapace of a Gravios, capable of withstanding lava. Feels heavy enough to split the very earth.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Gravios-U-Rüstung', 'Gravios U Armor', 'armor', 1, '{"max_level":3,"element_resist":{"fire":"resist","water":"weak","thunder":"strong_resist","non_elemental":"very_weak"}}', '[]', '[]', 'Rüstung aus dem härteren und zäheren Schwarzen Gravios. Sie ist so furchteinflößend, dass sich sogar die Luft schwer anfühlt.', 'Armor made from the tougher and darker Black Gravios. So intimidating, the very air will feel heavy.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Rey-Dau-Rüstung', 'Rey Dau Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"weak","thunder":"very_weak","ice":"resist","dragon":"strong_resist"}}', '[]', '[]', 'Rey-Dau-Rüstung. Ihr Ehrfurcht erweckendes Aussehen ist Beweis, dass dieses Monster vor niemandem zurückweicht.', 'Rey Dau armor. Its crest reaches the heavens—proof that this creature bows to no one.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Tigrex-Rüstung', 'Tigrex Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"resist","ice":"strong_resist"}}', '[]', '[]', 'Rüstung aus einem Tigrex. Ein Symbol für absolute Macht sowie für mutwillige Zerstörung.', 'Armor made from a Tigrex. A symbol of absolute power. A symbol of wanton destruction.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Tigrex-U-Rüstung', 'Tigrex U Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"resist","thunder":"strong_resist"}}', '[]', '[]', 'Rüstung aus einem Brachial-Tigrex. Der dunkle Rückenpanzer ist mit Erinnerungen an absolute Macht getränkt.', 'Armor made from a Brute Tigrex. Its dark carapace is etched with the memories of absolute power.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Zinogre-Rüstung', 'Zinogre Armor', 'armor', 1, '{"max_level":3,"element_resist":{"thunder":"very_weak","ice":"resist","dragon":"strong_resist","non_elemental":"weak"}}', '[]', '[]', 'Rüstung aus Materialien eines Zinogre. Einzigartige Kräfte wurden mit großem Geschick darin versiegelt.', 'Armor made using materials from a Zinogre. With great skill, its peerless power has been sealed within.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Zinogre-U-Rüstung', 'Zinogre U Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"weak","thunder":"very_weak","ice":"strong_resist","non_elemental":"resist"}}', '[]', '[]', 'Rüstung aus einem Höllen-Zinogre, enthält die versteckte Kraft der Drachen. Sogar Monster erzittern vor ihrer Kraft.', 'Armor made from a Stygian Zinogre, containing the hidden power of dragons. Even monsters will tremble before its power.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Artian-Rüstung', 'Artian Armor', 'armor', 1, '{"max_level":3,"element_resist":{"thunder":"very_weak","ice":"strong_resist","dragon":"weak","non_elemental":"resist"}}', '[]', '[]', 'Starre Rüstung aus unbekanntem Metall, das selbst Kunsthandwerker verblüfft.', 'Rigid armor made from an unknown metal that astounded artisans when it was excavated.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Hochmetall-Rüstung', 'High Metal Armor', 'armor', 1, '{"max_level":3,"element_resist":{"fire":"weak","thunder":"very_weak","ice":"strong_resist","dragon":"resist"}}', '[]', '[]', 'Rüstung aus seltenem Erz. Nur schwer zu beschädigen.', 'Armor made from rare ore. Very difficult to damage.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Blango-Rüstung', 'Blango Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"strong_resist","dragon":"resist"}}', '[]', '[]', 'Göttlich strahlende Rüstung aus Blangonga-Teilen. Dieses Meisterwerk aus dem Osten stärkt die Verteidigung.', 'Divinely majestic armor made from Blangonga parts. This masterpiece of Eastern craftsmanship boasts surprising defense.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Legiana-Rüstung', 'Legiana Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"strong_resist","thunder":"weak","ice":"very_weak","dragon":"resist"}}', '[]', '[]', 'Diese Rüstung lässt es so aussehen, als wärst du in die Schwingen eines Legiana gehüllt. Ohne Frage der Stil eines einsamen Kriegers.', 'With this armor, you can look as if you are wrapped in Legiana wings. Has a lonesome warrior feel to it.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Goss-Harag-Rüstung', 'Goss Harag Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"strong_resist","thunder":"very_weak","dragon":"resist","non_elemental":"weak"}}', '[]', '[]', 'Rüstung aus Goss-Harag-Materialien. Durch ihr imposantes Aussehen werden weinende Kinder still und tapfere Krieger zittern vor Angst.', 'Armor made from Goss Harag materials. Its imposing appearance silences crying children and makes hardy warriors shudder with fear.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Lunagaron-Rüstung', 'Lunagaron Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"strong_resist","thunder":"weak","dragon":"resist","non_elemental":"very_weak"}}', '[]', '[]', 'Diese Rüstung ist voller Wildheit eines Lunagaron. Verleiht dem Träger die Widerstandskraft und Beweglichkeit des Monsters.', 'Armor that embodies Lunagaron''s ferocity. Bestows the monster''s resilience and agility upon the wearer.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Rathalos-Rüstung', 'Rathalos Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"resist","ice":"very_weak","dragon":"weak","non_elemental":"strong_resist"}}', '[]', '[]', 'Rüstung des Königs der Lüfte, Rathalos. Man sagt, dass es keine Flamme in der Welt gibt, die sie versengen kann.', 'Armor of the King of the Skies, Rathalos. It is said that no flame exists which will scorch this armor.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Rath.seelen-Rüst.', 'Rath Soul Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"resist","ice":"weak","dragon":"very_weak","non_elemental":"strong_resist"}}', '[]', '[]', 'Rüstung mit der Kraft des Azurnen Rathalos, dem König der Lüfte. Alle, die ihre Pracht erblicken, werden den Morgen nicht mehr erleben.', 'Armor containing the power of the Azure Rathalos, King of the Blue Skies. Those who witness it will never see daybreak again.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Finsterrüstung', 'Sinister Armor', 'armor', 1, '{"max_level":3,"element_resist":{"fire":"weak","water":"resist","thunder":"strong_resist","ice":"very_weak"}}', '[]', '[]', 'Rüstung, die vom Groll eines Magnamalos erfüllt wurde. Das Böse in ihr verschlingt alles... selbst ihren Träger.', 'Armor seething with the malice of a Magnamalo. The evil lurking within devours all, even the wearer.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Arkvulkan-Rüstung', 'Arkvulcan Armor', 'armor', 1, '{"max_level":3,"element_resist":{"fire":"very_weak","water":"resist","thunder":"weak","ice":"weak","dragon":"weak","non_elemental":"strong_resist"}}', '[]', '[]', 'Rüstung aus Arkveld-Materialien. Getragen von einem Ritter, der sein Königreich verlor und die Welt neu gestaltete.', 'Armor made from Arkveld spoils. The design was worn by a knight left kingdomless who reshaped the world.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Barioth-Rüstung', 'Barioth Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"strong_resist","thunder":"weak","ice":"very_weak","dragon":"resist"}}', '[]', '[]', 'Rüstung aus einem Barioth. Der schneeweiße Rückenpanzer birgt den Kampfgeist der gefrorenen Ebenen.', 'Armor made from a Barioth. The fighting spirit of the frozen wastes lies within its snow-white carapace.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Barioth-U-Rüstung', 'Barioth U Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"resist","thunder":"weak","ice":"very_weak","dragon":"strong_resist"}}', '[]', '[]', 'Rüstung aus der gegerbten Haut eines Sand-Barioth. Erinnert an den heißen Sand, der durch die Wüste gepustet wird.', 'Armor made from the tan hide of a Sand Barioth. Reminiscent of the tornadoes of hot sand blowing through the desert.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Damaskus-Rüstung', 'Damascus Armor', 'armor', 1, '{"max_level":3,"element_resist":{"fire":"weak","water":"very_weak","thunder":"resist","ice":"strong_resist"}}', '[]', '[]', 'Stahlrüstung, die ihrem Träger Ruhm bringt. Nur wenige bekommen sie je zu sehen.', 'Steel armor said to lead its wearer to glory. Rarely glimpsed in a lifetime.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Malzeno-Rüstung', 'Malzeno Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"very_weak","thunder":"resist","ice":"weak","non_elemental":"strong_resist"}}', '[]', '[]', 'Rüstung aus einem blutrünstigen Malzeno. Sie jagt allen Lebewesen Angst ein.', 'Armor made from a bloodthirsty Malzeno. Strikes fear into the hearts of all living creatures.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Namielle-Rüstung', 'Tentacle Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"strong_resist","thunder":"resist","ice":"weak","non_elemental":"very_weak"}}', '[]', '[]', 'Namielle-Rüstung, die ihren Träger in Dunkelheit hüllt. Nur mit starkem Herzen kann man ihrem Wahnsinn widerstehen.', 'Namielle armor that swathes the wearer in darkness. Only those with a stout heart can resist the madness of the abyss.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Velkhana-Rüstung', 'Rimeguard Armor', 'armor', 1, '{"max_level":3,"element_resist":{"water":"strong_resist","thunder":"weak","dragon":"resist","non_elemental":"very_weak"}}', '[]', '[]', 'Schmück dich mit den dornigen Eiszapfen dieser prachtvollen Velkhana-Rüstung, die dem Träger die Sicht verdecken.', 'Adorn yourself in thorny icicles with this gorgeous Velkhana armor that obscures the wearer''s eyes.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Eisenschwert', 'Iron Sword', 'greatsword', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3}', '[]', '[]', 'Ein Großschwert, mit feinem Gespür für Schwertkampf geschmiedet. Kann einen mächtigen Stoß entfesseln.', 'Great sword made with a fine understanding of the basics of swordplay. Capable of unleashing a powerful blow.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Katzenseele', 'Cat''s Soul', 'greatsword', 1, '{"attack":15,"defense":0,"critical":0,"max_level":3,"status":"sleep","status_rate":8}', '[]', '[]', 'Großschwert mit einem Gesicht. Es wird wohl von der Seele einer Felyne bewohnt, die kämpfte, um ihren Meister zu verteidigen.', 'Great sword with a face. Said to hold the soul of a Felyne who fought valiantly in defense of their master.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Chrom-Rasiermesser', 'Chrome Razor', 'greatsword', 1, '{"attack":15,"defense":0,"critical":10,"max_level":3,"status":"poison","status_rate":8}', '[]', '[]', 'Großschwert, geschmiedet mit dem Ziel, die schärfste Schneide der Welt zu kreieren. Die Klinge ist mit tödlichem Gift überzogen.', 'Great sword made in pursuit of honing the sharpest edge known to mankind. The blade is coated in a deadly poison.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Azur-Schlangenklinge', 'Azure Serpentblade', 'greatsword', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3}', '[]', '[]', 'Ein Großschwert, das der Verwüsterklinge nachempfunden wurde. Die scharfen Velocidrome-Fangzähne verleihen ihm zusätzliche Angriffskraft.', 'Great sword modeled after the Ravager Blade. It is made with the sharp fangs of the Velocidrome for extra offensive power.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Nerscylla-Klinge', 'Scylla Blade', 'greatsword', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"status":"blast","status_rate":8}', '[]', '[]', 'Ein Großschwert, das die Härte von Nerscylla-Materialien ausnutzt. Seine unglaubliche Klinge kann wirklich alles zerteilen.', 'Great sword made to utilize the hard materials taken from a Nerscylla. Its incredible blade can cleave anything in two.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Izuchi-Klinge', 'Izuchi Blade', 'greatsword', 1, '{"attack":15,"defense":0,"critical":15,"max_level":3}', '[]', '[]', 'Ein Großschwert aus Izuchi-Teilen. So gut zu handhaben, wie Izuchi wendig sind.', 'A great sword made of Izuchi parts. Izuchi are nimble, so the handling is great.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Rückenpanzerschwert', 'Carapace Sword', 'greatsword', 1, '{"attack":35,"defense":15,"critical":0,"max_level":3}', '[]', '[]', 'Eine Klinge in Form eines Barroth-Kopfes. Sie ist auch beinahe genauso hart.', 'A blade shaped like a Barroth''s head; it packs nearly as much punch.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Golm-Klinge', 'Golm Blade', 'greatsword', 1, '{"attack":35,"defense":10,"critical":0,"max_level":3}', '[]', '[]', 'Ein Garangolm-Großschwert. Rustikal, bietet aber gute Verteidigung.', 'A Garangolm great sword, its rustic construction emphasizing weighty and sturdy defense.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Sentoryu-Rabe', 'Sentoryu Raven', 'greatsword', 1, '{"attack":15,"defense":0,"critical":10,"max_level":3,"status":"poison","status_rate":8}', '[]', '[]', 'Eine schwarze Klinge aus Yian-Garuga-Teilen, die absolut alles durchschneiden kann.', 'A black blade made from Yian Garuga parts. Can slice up anything that approaches it.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Tigrex-Kieferklinge', 'Tiger Jawblade', 'greatsword', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3}', '[]', '[]', 'Großschwert, basierend auf den riesigen Fangzähnen eines Tigrex. Ein Schwung wird alles zerfetzen.', 'Great sword based on the huge fangs of the Tigrex. One swing will reduce anything to shreds.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Cheda-Klinge', 'Cheda Blade', 'greatsword', 1, '{"attack":15,"defense":0,"critical":10,"max_level":3}', '[]', '[]', 'Großschwert, das in Seregios-Schuppen gehüllt ist. Jeder Hieb verursacht zahllose quälende Schnitte.', 'Great sword clad in the scales of a Seregios. Each swing inflicts countless painful slashes.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Finsterklinge', 'Sinister Blade', 'greatsword', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"status":"paralysis","status_rate":10}', '[]', '[]', 'Ein Schwert, gefertigt aus dem Tückischen Wyvern. Glänzt, als würde es dessen Geist in sich tragen.', 'A sword from the Wyvern of Malice. It gleams slightly, as if home to its spirit.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Huhn-Enthaupter', 'Chicken Decapitator', 'greatsword', 1, '{"attack":15,"defense":0,"critical":0,"max_level":3,"element":"fire"}', '[]', '[]', 'Schönes Großschwert, das an Yian-Kut-Ku-Flügel erinnert. Geschmiedet mit sorgfältiger Handwerkskunst.', 'A fine great sword reminiscent of the wings of a Yian Kut-Ku. Made with exceptionally diligent craftsmanship.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Aknosom-Klinge', 'Aknosom Blade', 'greatsword', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"fire"}', '[]', '[]', 'Ein Großschwert aus sorgfältig geschliffenen Aknosom-Teilen, die zart schimmern.', 'A great sword consisting of gently honed Aknosom parts that give it a fine shimmer.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Walkürenklinge', 'Valkyrie Blade', 'greatsword', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"fire","status":"poison","status_rate":8}', '[]', '[]', 'Großschwert aus wunderschönen Rathian-Materialien. Die Klinge ist mit Gift versehen, das Feinde schnell und effektiv erledigt.', 'Great sword crafted from beautiful Rathian materials. The blade is coated in venom to bring down foes fast and hard.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Flammenzahn', 'Flammenzahn', 'greatsword', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"fire"}', '[]', '[]', 'Ein Großschwert aus den allerbesten Anjanath-Reißzähnen, das dem Träger ermöglicht, Beute in Sekundenschnelle zu zerfetzen.', 'A great sword crafted with the finest Anjanath fangs, allowing its wielder to rip apart prey in mere seconds.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Rosenbrett', 'Rosenbrett', 'greatsword', 1, '{"attack":15,"defense":0,"critical":10,"max_level":3,"element":"fire","status":"poison","status_rate":8}', '[]', '[]', 'Espinas-Großschwert mit scharfen, zornigen Stacheln, die niemals zerbrechen.', 'Espinas great sword. Lined with sharp, raged-filled spikes that can never break.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Sengender Loher', 'Scorching Blazer', 'greatsword', 1, '{"attack":15,"defense":0,"critical":0,"max_level":3,"element":"fire"}', '[]', '[]', 'Nach dem Abbild des Schwanzes eines Glavenus gefertigt. Greift mit einem Hagel gewaltiger Hiebe an.', 'Modeled after the tail of the Glavenus. Attacks with a flurry of violent slashes.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Rathalos-Feuerschwert', 'Rathalos Firesword', 'greatsword', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"fire"}', '[]', '[]', 'Großschwert, geschmiedet als Abbild eines Rathalos-Flügels. Seine rot glühenden Materialien erzeugen beim Schlag lodernde Flammen.', 'Great sword made in the image of a Rathalos wing. The red-hot materials used in its forging generate a flaming strike.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Tetranadon-Schneide', 'Tetranadon Edge', 'greatsword', 1, '{"attack":35,"defense":10,"critical":0,"max_level":3,"element":"water"}', '[]', '[]', 'Ein Großschwert aus einem geschärften Tetra- Schnabel. Die Schneide ist ein wenig feucht.', 'A great sword made from a sharpened Tetranadon beak. The edge is slightly moist.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Ceanatauren-Klinge', 'Ceanataur Blade', 'greatsword', 1, '{"attack":15,"defense":0,"critical":0,"max_level":3,"element":"water"}', '[]', '[]', 'Ein scharfes Großschwert aus einem blauen Panzer. Die Klinge besteht aus feinsten Materialien.', 'Sharp great sword made from a blue shell. Only the finest materials are used in its blade.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Hanayako Yohino', 'Hanayako Yohino', 'greatsword', 1, '{"attack":15,"defense":0,"critical":10,"max_level":3,"element":"water"}', '[]', '[]', 'Großschwert eines gelehrten Samurai. Die Blüten lassen den Tod erblühen.', 'A great sword of a refined, educated samurai. These petals blossom with death.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Khezu-Schockschwert', 'Khezu Shock Sword', 'greatsword', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"thunder"}', '[]', '[]', 'Großschwert aus Khezu-Haut. Es kann durch das an der Klinge montierte Stromreservoir die Kraft von Blitzen gewähren.', 'Great sword made using the hide of a Khezu. Granted the power of lightning by the electric reservoir mounted on the blade.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Donnerzahn', 'Donnerzahn', 'greatsword', 1, '{"attack":15,"defense":0,"critical":15,"max_level":3,"element":"thunder"}', '[]', '[]', 'Blitze tanzen über dieses Fulgur-Anjanath-Großschwert, das jeden Feind in Stücke hackt.', 'Lightning dances upon the blade of this Fulgur Anjanath great sword as it cleaves prey in two.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Lagiacrus-Klinge', 'Lagiacrus Blade', 'greatsword', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"thunder"}', '[]', '[]', 'In Lagiacrus-Blitze gehülltes Schwert. Stabil genug, seiner eigenen Elektrizität standhalten zu können.', 'Sword clad in the lightning of the Lagiacrus. Sturdy enough to withstand its own electrical discharges.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Gefrorener Speerthunfisch', 'Frozen Speartuna', 'greatsword', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"ice"}', '[]', '[]', 'Ein Speerthunfisch, komplett eingefroren. Beweis meisterlicher Angelfähigkeiten, aber gleichzeitig auch ein Großschwert.', 'A Speartuna, frozen solid. Proof of one''s status as a master angler, but it also doubles as a great sword.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Goss-Klinge', 'Gossblade', 'greatsword', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"ice"}', '[]', '[]', 'Dieses spitze Großschwert aus Goss-Harag-Teilen hat eine eiskalte Aura.', 'Made from Goss Harag parts, this sharp-pointed great sword has a chilling aura.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Schwert des Wintermonds', 'Sword of Winter Moon', 'greatsword', 1, '{"attack":15,"defense":0,"critical":0,"max_level":3,"element":"ice"}', '[]', '[]', 'Lunagarons Wildheit in Form eines Großschwerts. Das Schaudern, das man in seiner Nähe spürt, könnte bloß Angst sein...', 'Lunagaron''s ferocity embodied in a great sword. The chill felt on approach might just be fear...');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Epitaph-Klinge', 'Epitaph Blade', 'greatsword', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"dragon"}', '[]', '[]', 'Eine Klinge unbekannter Herkunft. Sie trägt eine Inschrift, aber was bedeutet sie?', 'A blade of unknown origins. It has an inscription, but what could it mean?');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Berserker-Schwert', 'Berserker Sword', 'greatsword', 1, '{"attack":35,"defense":0,"critical":0,"max_level":3,"element":"dragon"}', '[]', '[]', 'Enormes Großschwert, das die Kraft eines Dämonjho beinhaltet. Feinde werden durch seine brutalen Angriffe zu Staub zermahlen.', 'Enormous great sword containing the power of the Deviljho. Pulverizes foes with brutal attacks.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Veldian Gladius', 'Veldian Gladius', 'greatsword', 1, '{"attack":25,"defense":0,"critical":0,"max_level":3,"element":"dragon"}', '[]', '[]', 'Ein Großschwert, gefertigt aus Arkveld-Materialien. Ein Spiegelbild des tapferen Trägers und nach dem Aufladen ein Ausbund des Zorns.', 'Great sword crafted from Arkveld materials. A mirror of its valiant wielder, it is the picture of fury when charged.');
INSERT INTO equipment (name_de, name_en, type, rarity, stats, materials_de, materials_en, description_de, description_en) VALUES ('Blauer-Ältester-Großschwert', 'Azure Elder Great Sword', 'greatsword', 1, '{"attack":15,"defense":0,"critical":0,"max_level":3,"element":"dragon"}', '[]', '[]', 'Ein tiefblaues Großschwert mit einer Schneide, die ihr Ziel so flink zerteilt wie der Wind vor einem Sturm.', 'A deep-blue great sword with an edge that cuts as swiftly as the wind before a storm.');